func Store(t *testing.T) *ociresource.KVStore {
	t.Helper()
	token := rand.Text()
	broker, err := server.NewServer(&server.Options{Host: "127.0.0.1", Port: -1, JetStream: true,
		StoreDir: filepath.Join(t.TempDir(), "jetstream"), Authorization: token})
	if err != nil {
		t.Fatal(err)
	}
	broker.Start()
	t.Cleanup(func() { broker.Shutdown(); broker.WaitForShutdown() })
	if !broker.ReadyForConnections(5 * time.Second) {
		t.Fatal("OCI integration broker did not become ready")
	}
	connection, err := nats.Connect(broker.ClientURL(), nats.Token(token))
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(connection.Close)
	js, err := jetstream.New(connection)
	if err != nil {
		t.Fatal(err)
	}
	store, err := ociresource.OpenKVStore(t.Context(), js, 1)
	if err != nil {
		t.Fatal(err)
	}
	return store
}

func Server(t *testing.T, handler http.HandlerFunc) (*ociclient.Factory, string) {
	t.Helper()
	key, err := rsa.GenerateKey(rand.Reader, 2048)
	if err != nil {
		t.Fatal(err)
	}
	provider := common.NewRawConfigurationProvider("ocid1.tenancy.oc1..t", "ocid1.user.oc1..u", Region, "fp",
		string(pem.EncodeToMemory(&pem.Block{Type: "RSA PRIVATE KEY", Bytes: x509.MarshalPKCS1PrivateKey(key)})), nil)
	factory, err := ociclient.New(provider, ociclient.Options{Region: Region})
	if err != nil {
		t.Fatal(err)
	}
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Header.Get("Authorization") == "" {
			t.Errorf("unsigned %s %s", r.Method, r.URL.Path)
			http.Error(w, "unsigned", http.StatusUnauthorized)
			return
		}
		handler(w, r)
	}))
	t.Cleanup(server.Close)
	return factory, server.URL
}

func (c *Controller[S, O]) Reconcile(ctx context.Context, epoch uint64) (Result, error) {
	ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
	defer cancel()
	c.mu.Lock()
	defer c.mu.Unlock()
	if err := c.validate(); err != nil {
		return Result{}, err
	}
	records, err := c.Store.List(ctx, c.Region, c.Resource.Kind())
	if err != nil {
		return Result{}, err
	}
	var result Result
	var failures []error
	for _, desired := range records {
		status, err := c.reconcileOne(ctx, epoch, desired)
		result.Observed++
		switch {
		case status.Deleted:
			result.Deleted++
		case status.Foreign:
			result.Foreign++
		case status.InSync:
			result.InSync++
		default:
			result.Drifted++
		}
		if status.Applied {
			result.Applied++
		}
		if err != nil {
			result.Failed++
			status.Error = err.Error()
			if errors.Is(err, ErrFenced) || ctx.Err() != nil {
				return result, err
			}
			failures = append(failures, fmt.Errorf("%s: %w", desired.Key, err))
		}
		if !status.Deleted {
			if err := c.Store.PutStatus(ctx, status); err != nil {
				return result, err
			}
		}
	}
	return result, errors.Join(failures...)
}

func (c *Controller[S, O]) guard(ctx context.Context, epoch uint64) error {
	if err := c.Authority.Guard(ctx, epoch); err != nil {
		return fmt.Errorf("%w: %w", ErrFenced, err)
	}
	return nil
}

func (c *Controller[S, O]) reconcileOne(ctx context.Context, epoch uint64, desired Desired) (Status, error) {
	status := Status{Key: desired.Key, Generation: desired.Generation, SpecDigest: desired.SpecDigest, ObservedAt: c.now(),
		Policy: desired.Policy}
	if desired.Operation != nil {
		status.OperationID = desired.Operation.ID
	}
	if desired.Key.Region != c.Region || desired.Key.Kind != c.Resource.Kind() {
		return status, errors.New("OCI desired record is outside this controller's scope")
	}
	var spec S
	if err := json.Unmarshal(desired.Spec, &spec, json.RejectUnknownMembers(true)); err != nil {
		return status, fmt.Errorf("decode OCI desired spec: %w", err)
	}
	target := Target[S]{Key: desired.Key, Generation: desired.Generation, SpecDigest: desired.SpecDigest,
		Ownership: c.Ownership, Spec: spec, Deleting: desired.Tombstone != nil,
		Guard: func(ctx context.Context) error {
			if err := c.guard(ctx, epoch); err != nil {
				return err
			}
			var err error
			desired, err = c.Store.SaveOperation(ctx, desired, epoch, c.now(), false)
			if err != nil {
				return err
			}
			return c.guard(ctx, epoch)
		}}
	bindOperation := func(ctx context.Context) context.Context {
		target.OperationID = desired.Operation.ID
		status.OperationID = target.OperationID
		ctx = ociclient.WithWireAttempt(ctx, func(request *http.Request) (func(*http.Response, error, bool) error, error) {
			return checkpointRequest(request.Context(), request, &desired, c.Store, epoch, c.now)
		})
		return context.WithValue(ociclient.WithAuthority(ctx, target.Fence), operationContextKey{}, operationContext{id: target.OperationID,
			record: func(ctx context.Context, id string) error {
				if id == "" {
					return errors.New("OCI mutation returned no work request")
				}
				if err := c.guard(ctx, epoch); err != nil {
					return err
				}
				if !slices.Contains(desired.Operation.WorkRequests, id) {
					operation := *desired.Operation
					operation.WorkRequests = append(slices.Clone(operation.WorkRequests), id)
					desired.Operation = &operation
				}
				var err error
				desired, err = c.Store.SaveOperation(ctx, desired, epoch, c.now(), false)
				return err
			}})
	}
	if desired.Operation != nil && len(desired.Operation.WorkRequests) != 0 {
		// Reading an original accepted work request needs live authority but
		// must not claim a new mutation before its outcome is known.
		if err := c.guard(ctx, epoch); err != nil {
			return status, err
		}
		recovery, ok := any(c.Resource).(interface {
			RecoverWorkRequests(context.Context, []string) error
		})
		if !ok {
			return status, errors.New("OCI resource cannot recover its pending work requests")
		}
		recoveryErr := recovery.RecoverWorkRequests(bindOperation(ctx), desired.Operation.WorkRequests)
		if recoveryErr != nil && !errors.Is(recoveryErr, ErrWorkRequestFailed) {
			return status, fmt.Errorf("recover OCI work request: %w", recoveryErr)
		}
		operation := *desired.Operation
		operation.WorkRequests = nil
		if recoveryErr != nil {
			operation.Failure = recoveryErr.Error()
		}
		desired.Operation = &operation
		if recoveryErr != nil {
			if err := c.guard(ctx, epoch); err != nil {
				return status, err
			}
			var err error
			desired, err = c.Store.SaveOperation(ctx, desired, epoch, c.now(), true)
			if err != nil {
				return status, err
			}
			return status, fmt.Errorf("previous OCI operation failed: %w", recoveryErr)
		}
		if err := c.guard(ctx, epoch); err != nil {
			return status, err
		}
	}
	observed, found, err := c.Resource.Observe(ctx, target)
	if errors.Is(err, ErrForeign) {
		// Never adopt, mutate, or delete an object this controller cannot prove
		// it owns; surface it for an operator instead.
		status.Found, status.Foreign = true, true
		slog.WarnContext(ctx, "withholding foreign OCI resource", "key", desired.Key.String())
		return status, nil
	}
	if err != nil {
		return status, fmt.Errorf("observe: %w", err)
	}
	status.Found = found

	if desired.Tombstone != nil {
		return c.deleteOne(ctx, epoch, &desired, target, observed, found, status, bindOperation)
	}

	plan := c.Resource.Diff(target, observed, found)
	status.Drift = plan.Changes
	status.InSync = plan.Empty()
	if plan.Empty() && desired.Operation != nil && desired.Operation.CompletedAt.IsZero() {
		if err := c.guard(ctx, epoch); err != nil {
			return status, err
		}
		status.OperationID = desired.Operation.ID
		_, err := c.Store.SaveOperation(ctx, desired, epoch, c.now(), true)
		if err != nil {
			return status, err
		}
	}
	if plan.Empty() {
		return status, nil
	}
	if desired.Operation != nil && !desired.Operation.AppliedAt.IsZero() {
		// The previous full apply finished; fresh observed drift needs new
		// tokens rather than deduplicating against that finished request.
		desired.Operation = nil
	}
	if err := target.Fence(ctx); err != nil {
		return status, err
	}
	ctx = bindOperation(ctx)
	if err := c.Resource.Apply(ctx, target, observed, found, plan); err != nil {
		return status, fmt.Errorf("apply: %w", err)
	}
	if err := c.guard(ctx, epoch); err != nil {
		return status, err
	}
	operation := *desired.Operation
	operation.AppliedAt = c.now()
	desired.Operation = &operation
	if _, err := c.Store.SaveOperation(ctx, desired, epoch, c.now(), false); err != nil {
		return status, err
	}
	status.Applied = true
	slog.InfoContext(ctx, "OCI resource drift corrected", "key", desired.Key.String(), "plan", plan.String())
	recordDecision(ctx, desired, epoch, decisionlog.KindOCIDriftCorrected,
		fmt.Sprintf("Corrected drift on %s (%d changes)", desired.Key, len(plan.Changes)),
		"The observed OCI resource differed from its enforced desired spec.", plan)
	return status, nil
}

func (c *Controller[S, O]) deleteOne(ctx context.Context, epoch uint64, desired *Desired, target Target[S], observed O,
	found bool, status Status, bindOperation func(context.Context) context.Context,
) (Status, error) {
	if c.now().Before(desired.Tombstone.NotBefore) {
		status.Drift = []Change{{Op: "delete", Detail: "waiting for tombstone not-before " + desired.Tombstone.NotBefore.Format(time.RFC3339)}}
		return status, nil
	}
	if err := target.Fence(ctx); err != nil {
		return status, err
	}
	target.OperationID = desired.Operation.ID
	status.OperationID = target.OperationID
	ctx = bindOperation(ctx)
	if found {
		if err := c.Resource.Delete(ctx, target, observed); err != nil {
			return status, fmt.Errorf("delete: %w", err)
		}
		status.Applied = true
		// Re-observe on the next pass before purging, so a delete whose
		// response was lost is confirmed rather than assumed.
		status.Drift = []Change{{Op: "delete", Detail: "awaiting confirmation"}}
		recordDecision(ctx, *desired, epoch, decisionlog.KindOCIResourceDeleted,
			"Deleted the managed parts of "+desired.Key.String(),
			"Its desired record was tombstoned and the not-before instant passed.", Plan{})
		return status, nil
	}
	if err := c.Store.Purge(ctx, *desired); err != nil {
		return status, fmt.Errorf("purge desired record: %w", err)
	}
	status.Deleted = true
	recordDecision(ctx, *desired, epoch, decisionlog.KindOCIResourceReleased,
		"Released "+desired.Key.String()+" from reconcile",
		"A pass after the tombstone confirmed nothing managed is left.", Plan{})
	return status, nil
}

type Target[S any] struct {
	Key        Key
	Generation uint64
	SpecDigest string
	Ownership  Ownership
	Spec       S
	// OperationID is durable before Apply/Delete and retained until OCI
	// observation confirms convergence, including after a leader restart.
	OperationID string
	// Deleting is set when the desired record is tombstoned. A resource that
	// is part of a larger object (rules of an NSG, backends of an NLB) reports
	// found=false once none of its managed parts remain.
	Deleting bool
	// Guard re-checks mutation authority. The controller sets it; Apply and
	// Delete call Fence before every individual mutation, so a controller
	// that loses leadership mid-pass stops instead of finishing its plan.
	Guard func(context.Context) error
}

// Fence re-checks mutation authority immediately before one mutation.
func (t Target[S]) Fence(ctx context.Context) error {
	if t.Guard == nil {
		return ErrFenced
	}
	return t.Guard(ctx)
}

func NewDesired(key Key, generation uint64, policy DriftPolicy, spec any) (Desired, error) {
	wire, err := json.Marshal(spec, json.Deterministic(true))
	if err != nil {
		return Desired{}, fmt.Errorf("encode OCI desired spec: %w", err)
	}
	desired := Desired{SchemaVersion: schemaVersion, Key: key, Generation: generation, Policy: policy,
		Spec: jsontext.Value(wire), SpecDigest: digest(wire)}
	return desired, desired.Validate()
}

func digest(wire []byte) string {
	sum := sha256.Sum256(wire)
	return hex.EncodeToString(sum[:])
}

// Validate checks the record shape and that the digest binds the spec bytes.
func (d Desired) Validate() error {
	if d.SchemaVersion != schemaVersion || d.Generation == 0 || !d.Policy.valid() || len(d.Spec) == 0 {
		return errors.New("OCI desired record has an unsupported version, generation, policy, or spec")
	}
	if err := d.Key.Validate(); err != nil {
		return err
	}
	if digest(d.Spec) != d.SpecDigest {
		return errors.New("OCI desired record spec does not match its digest")
	}
	if d.Tombstone != nil && (d.Tombstone.RequestedAt.IsZero() || d.Tombstone.NotBefore.Before(d.Tombstone.RequestedAt)) {
		return errors.New("OCI desired record tombstone is invalid")
	}
	if d.Operation != nil {
		return d.Operation.validate()
	}
	return nil
}

func OpenKVStore(ctx context.Context, js jetstream.JetStream, replicas int) (*KVStore, error) {
	if js == nil || replicas < 1 || replicas > 5 {
		return nil, errors.New("OCI resource store requires JetStream and one to five replicas")
	}

	desired, err := openBucket(ctx, js, replicas, desiredBucket, "Desired OCI regional resource specs", 5)
	if err != nil {
		return nil, err
	}
	observed, err := openBucket(ctx, js, replicas, observedBucket, "Last observed OCI regional resource state and drift", 1)
	if err != nil {
		return nil, err
	}
	return &KVStore{desired: desired, observed: observed}, nil
}

func openBucket(ctx context.Context, js jetstream.JetStream, replicas int, bucket, description string, history uint8) (jetstream.KeyValue, error) {
	kv, err := js.CreateKeyValue(ctx, jetstream.KeyValueConfig{Bucket: bucket, Description: description,
		MaxValueSize: maxRecordBytes, History: history, Storage: jetstream.FileStorage, Replicas: replicas, Compression: true})
	if err == nil {
		return kv, nil
	}
	if !errors.Is(err, jetstream.ErrBucketExists) {
		return nil, fmt.Errorf("create %s bucket: %w", bucket, err)
	}
	kv, err = js.KeyValue(ctx, bucket)
	if err != nil {
		return nil, fmt.Errorf("open %s bucket: %w", bucket, err)
	}
	status, err := kv.Status(ctx)
	if err != nil {
		return nil, fmt.Errorf("inspect %s bucket: %w", bucket, err)
	}
	config := status.Config()
	if config.Replicas != replicas || config.Storage != jetstream.FileStorage || config.MaxValueSize > maxRecordBytes {
		return nil, fmt.Errorf("existing %s bucket has incompatible durability limits", bucket)
	}
	return kv, nil
}

func (s *KVStore) List(ctx context.Context, region, kind string) ([]Desired, error) {
	probe := Key{Region: region, Kind: kind, Name: "x"}
	if err := probe.Validate(); err != nil {
		return nil, err
	}
	lister, err := s.desired.ListKeysFiltered(ctx, region+"."+kind+".*")
	if err != nil {
		if errors.Is(err, jetstream.ErrNoKeysFound) {
			return nil, nil
		}
		return nil, fmt.Errorf("list OCI desired keys: %w", err)
	}
	var keys []string
	seen := make(map[string]bool)
	for key := range lister.Keys() {
		if len(keys) >= maxListedKeys {
			_ = lister.Stop()
			return nil, errors.New("OCI desired key list exceeds its safety bound")
		}
		if !seen[key] {
			seen[key] = true
			keys = append(keys, key)
		}
	}
	// The lister closes early without an error when ctx ends mid-listing;
	// a truncated listing must not look complete.
	if err := ctx.Err(); err != nil {
		return nil, fmt.Errorf("list OCI desired keys: %w", err)
	}
	slices.Sort(keys)
	records := make([]Desired, 0, len(keys))
	for _, subject := range keys {
		entry, err := s.desired.Get(ctx, subject)
		if errors.Is(err, jetstream.ErrKeyNotFound) {
			continue
		}
		if err != nil {
			return nil, fmt.Errorf("read OCI desired record: %w", err)
		}
		desired, err := decodeDesired(entry.Value(), entry.Revision())
		if err != nil {
			return nil, err
		}
		if desired.Key.subject() != subject {
			return nil, errors.New("OCI desired record key differs from its bucket key")
		}
		records = append(records, desired)
	}
	return records, nil
}

func (s *KVStore) Get(ctx context.Context, key Key) (Desired, error) {
	if err := key.Validate(); err != nil {
		return Desired{}, err
	}
	entry, err := s.desired.Get(ctx, key.subject())
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return Desired{}, ErrNotFound
	}
	if err != nil {
		return Desired{}, fmt.Errorf("read OCI desired record: %w", err)
	}
	desired, err := decodeDesired(entry.Value(), entry.Revision())
	if err != nil {
		return Desired{}, err
	}
	if desired.Key != key {
		return Desired{}, errors.New("OCI desired record key differs from its bucket key")
	}
	return desired, nil
}

func (s *KVStore) Put(ctx context.Context, desired Desired) (Desired, error) {
	desired.Operation = nil
	if err := desired.Validate(); err != nil {
		return Desired{}, err
	}
	wire, err := encode(desired)
	if err != nil {
		return Desired{}, err
	}
	current, err := s.Get(ctx, desired.Key)
	switch {
	case errors.Is(err, ErrNotFound):
		revision, err := s.desired.Create(ctx, desired.Key.subject(), wire)
		if errors.Is(err, jetstream.ErrKeyExists) {
			return Desired{}, ErrConflict
		}
		if err != nil {
			return Desired{}, fmt.Errorf("create OCI desired record: %w", err)
		}
		desired.Revision = revision
		return desired, nil
	case err != nil:
		return Desired{}, err
	}
	if desired.Generation <= current.Generation {
		return Desired{}, fmt.Errorf("%w: generation %d does not supersede %d", ErrConflict, desired.Generation, current.Generation)
	}
	if current.Operation != nil && current.Operation.CompletedAt.IsZero() {
		return Desired{}, fmt.Errorf("%w: previous OCI operation awaits observation", ErrConflict)
	}
	desired.Operation = nil
	wire, err = encode(desired)
	if err != nil {
		return Desired{}, err
	}
	revision, err := s.desired.Update(ctx, desired.Key.subject(), wire, current.Revision)
	if err != nil {
		return Desired{}, fmt.Errorf("%w: %w", ErrConflict, err)
	}
	desired.Revision = revision
	return desired, nil
}

func (s *KVStore) SaveOperation(ctx context.Context, desired Desired, epoch uint64, now time.Time, complete bool) (Desired, error) {
	if desired.Revision == 0 {
		return Desired{}, ErrConflict
	}
	desired, err := OperationRecord(desired, epoch, now, complete)
	if err != nil {
		return Desired{}, err
	}
	wire, err := encode(desired)
	if err != nil {
		return Desired{}, err
	}
	revision, err := s.desired.Update(ctx, desired.Key.subject(), wire, desired.Revision)
	if err != nil {
		return Desired{}, fmt.Errorf("%w: persist OCI operation: %w", ErrConflict, err)
	}
	desired.Revision = revision
	return desired, nil
}

// OperationRecord preserves an unfinished convergence's original identity and
// work requests. A store must durably CAS the returned record before effects.
func OperationRecord(desired Desired, epoch uint64, now time.Time, complete bool) (Desired, error) {
	if epoch == 0 || now.IsZero() {
		return Desired{}, errors.New("OCI operation requires an authority epoch and timestamp")
	}
	operation := Operation{ID: uuid.New().String(), Epoch: epoch, StartedAt: now.UTC()}
	if desired.Operation != nil && desired.Operation.CompletedAt.IsZero() {
		operation = *desired.Operation
		if epoch < operation.Epoch {
			return Desired{}, ErrFenced
		}
		operation.Epoch = epoch
	}
	if complete {
		operation.CompletedAt = now.UTC()
	}
	desired.Operation = &operation
	return desired, desired.Validate()
}

func (s *KVStore) MarkDeleted(ctx context.Context, key Key, requestedAt, notBefore time.Time) (Desired, error) {
	current, err := s.Get(ctx, key)
	if err != nil {
		return Desired{}, err
	}
	if current.Tombstone != nil {
		return current, nil
	}
	if current.Operation != nil && current.Operation.CompletedAt.IsZero() {
		return Desired{}, fmt.Errorf("%w: previous OCI operation awaits observation", ErrConflict)
	}
	current.Operation = nil
	current.Tombstone = &Tombstone{RequestedAt: requestedAt.UTC(), NotBefore: notBefore.UTC()}
	if err := current.Validate(); err != nil {
		return Desired{}, err
	}
	wire, err := encode(current)
	if err != nil {
		return Desired{}, err
	}
	revision, err := s.desired.Update(ctx, key.subject(), wire, current.Revision)
	if err != nil {
		return Desired{}, fmt.Errorf("%w: %w", ErrConflict, err)
	}
	current.Revision = revision
	return current, nil
}

func (s *KVStore) Purge(ctx context.Context, desired Desired) error {
	if desired.Tombstone == nil || desired.Revision == 0 {
		return errors.New("only a read tombstoned OCI desired record may be purged")
	}
	if err := s.desired.Purge(ctx, desired.Key.subject(), jetstream.LastRevision(desired.Revision)); err != nil {
		return fmt.Errorf("%w: %w", ErrConflict, err)
	}
	if err := s.observed.Purge(ctx, desired.Key.subject()); err != nil && !errors.Is(err, jetstream.ErrKeyNotFound) {
		return fmt.Errorf("purge OCI observed record: %w", err)
	}
	return nil
}

func (s *KVStore) PutStatus(ctx context.Context, status Status) error {
	if err := status.Key.Validate(); err != nil {
		return err
	}
	wire, err := encode(status)
	if err != nil {
		return err
	}
	if _, err := s.observed.Put(ctx, status.Key.subject(), wire); err != nil {
		return fmt.Errorf("write OCI observed record: %w", err)
	}
	return nil
}

func (s *KVStore) GetStatus(ctx context.Context, key Key) (Status, bool, error) {
	if err := key.Validate(); err != nil {
		return Status{}, false, err
	}
	entry, err := s.observed.Get(ctx, key.subject())
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return Status{}, false, nil
	}
	if err != nil {
		return Status{}, false, fmt.Errorf("read OCI observed record: %w", err)
	}
	var status Status
	if err := json.Unmarshal(entry.Value(), &status); err != nil {
		return Status{}, false, fmt.Errorf("decode OCI observed record: %w", err)
	}
	return status, true, nil
}

func Publish(ctx context.Context, store Store, key Key, policy DriftPolicy, spec Validator) (bool, error) {
	if err := key.Validate(); err != nil {
		return false, err
	}
	if err := spec.Validate(); err != nil {
		return false, fmt.Errorf("%s: %w", key, err)
	}
	generation := uint64(1)
	current, err := store.Get(ctx, key)
	switch {
	case errors.Is(err, ErrNotFound):
	case err != nil:
		return false, err
	default:
		if current.Tombstone != nil {
			return false, fmt.Errorf("%s: desired record is being deleted", key)
		}
		generation = current.Generation + 1
	}
	desired, err := NewDesired(key, generation, policy, spec)
	if err != nil {
		return false, err
	}
	if generation > 1 && desired.SpecDigest == current.SpecDigest && policy == current.Policy {
		return false, nil
	}
	if _, err := store.Put(ctx, desired); err != nil {
		return false, err
	}
	return true, nil
}

func requestAttempt(request *http.Request, now time.Time) (RequestAttempt, error) {
	deadline, ok := request.Context().Deadline()
	if !ok || !now.Before(deadline) || request.URL == nil || request.URL.User != nil {
		return RequestAttempt{}, errors.New("OCI mutation requires its original bounded request deadline and target")
	}
	attempt := RequestAttempt{Method: request.Method, URL: request.URL.String(), IfMatch: request.Header.Get("If-Match"),
		RetryToken: request.Header.Get("opc-retry-token"), StartedAt: now.UTC(), Deadline: deadline.UTC()}
	if request.Body != nil && request.Body != http.NoBody {
		if request.GetBody == nil {
			return RequestAttempt{}, errors.New("OCI mutation cannot checkpoint its exact request body")
		}
		body, err := request.GetBody()
		if err != nil {
			return RequestAttempt{}, err
		}
		defer body.Close()
		attempt.Body, err = io.ReadAll(io.LimitReader(body, maxRecordBytes+1))
		if err != nil || len(attempt.Body) > maxRecordBytes {
			return RequestAttempt{}, errors.Join(errors.New("OCI mutation request exceeds its byte bound"), err)
		}
	}
	return attempt, nil
}

func beginRequest(operation Operation, attempt RequestAttempt, now time.Time) (Operation, int, error) {
	operation.Requests = slices.Clone(operation.Requests)
	for _, previous := range operation.Requests {
		if previous.Uncertain() && !previous.sameRequest(attempt) {
			return Operation{}, 0, errors.New("uncertain original OCI request differs from retry bytes or token")
		}
	}
	for i, previous := range operation.Requests {
		if previous.sameRequest(attempt) {
			if !now.Before(previous.Deadline) {
				return Operation{}, 0, errors.New("original OCI request deadline expired; outcome needs observation")
			}
			// A retry retains the first deadline and exact bytes. A missing
			// outcome after this checkpoint remains uncertain on restart.
			previous.FinishedAt, previous.Status, previous.Sent = time.Time{}, 0, false
			operation.Requests[i] = previous
			return operation, i, nil
		}
	}
	if len(operation.Requests) >= 128 {
		return Operation{}, 0, errors.New("OCI operation request journal exceeds its bound")
	}
	operation.Requests = append(operation.Requests, attempt)
	return operation, len(operation.Requests) - 1, nil
}

func (o Operation) validate() error {
	if _, err := uuid.Parse(o.ID); err != nil || o.Epoch == 0 || o.StartedAt.IsZero() ||
		!o.CompletedAt.IsZero() && o.CompletedAt.Before(o.StartedAt) {
		return errors.New("OCI resource operation identity, epoch, or timestamps are invalid")
	}
	if len(o.WorkRequests) > 512 || len(o.Failure) > 4096 || !o.CompletedAt.IsZero() && len(o.WorkRequests) != 0 {
		return errors.New("OCI operation work requests exceed their bound or remain unfinished")
	}
	for _, id := range o.WorkRequests {
		if id == "" || len(id) > 1024 {
			return errors.New("OCI operation work request ID is invalid")
		}
	}
	if len(o.Requests) > 128 {
		return errors.New("OCI operation request journal exceeds its bound")
	}
	for _, request := range o.Requests {
		if request.Method == "" || request.URL == "" || len(request.URL) > 4096 || len(request.Body) > maxRecordBytes ||
			len(request.IfMatch) > 1024 || len(request.RetryToken) > 256 || request.StartedAt.Before(o.StartedAt) ||
			!request.Deadline.After(request.StartedAt) || !request.FinishedAt.IsZero() && request.FinishedAt.Before(request.StartedAt) ||
			request.Status < 0 || request.Status > 599 || request.Status != 0 && (!request.Sent || request.FinishedAt.IsZero()) {
			return errors.New("OCI operation request has invalid original bytes, deadline or outcome")
		}
	}
	return nil
}

func checkpointRequest(ctx context.Context, request *http.Request, desired *Desired, store Store, epoch uint64, now func() time.Time) (func(*http.Response, error, bool) error, error) {
	if desired.Operation == nil {
		return nil, errors.New("OCI wire request has no durable operation")
	}
	attempt, err := requestAttempt(request, now())
	if err != nil {
		return nil, err
	}
	operation, index, err := beginRequest(*desired.Operation, attempt, now())
	if err != nil {
		return nil, err
	}
	retained, cancel := context.WithDeadline(request.Context(), operation.Requests[index].Deadline)
	*request = *request.WithContext(retained)
	ctx = retained
	desired.Operation = &operation
	*desired, err = store.SaveOperation(ctx, *desired, epoch, now(), false)
	if err != nil {
		cancel()
		return nil, err
	}
	if err := ociclient.LimitAdmission(request.Context(), desired.Operation.Requests[index].Deadline); err != nil {
		cancel()
		return nil, err
	}
	return func(response *http.Response, _ error, sent bool) error {
		if response == nil || response.Body == nil {
			defer cancel()
		} else {
			// OCI decodes the response after dispatch returns. Keep its bounded
			// context live until that body closes rather than canceling early.
			response.Body = retainedRequestBody{ReadCloser: response.Body, cancel: cancel}
		}
		operation := *desired.Operation
		operation.Requests = slices.Clone(operation.Requests)
		attempt := operation.Requests[index]
		attempt.FinishedAt, attempt.Sent = now(), sent
		if response != nil && sent {
			attempt.Status = response.StatusCode
		}
		operation.Requests[index] = attempt
		desired.Operation = &operation
		updated, err := store.SaveOperation(ctx, *desired, epoch, now(), false)
		if err != nil {
			return fmt.Errorf("persist original OCI request outcome: %w", err)
		}
		*desired = updated
		return nil
	}, nil
}

func WithOperation(ctx context.Context, operationID string) context.Context {
	if existing, ok := ctx.Value(operationContextKey{}).(operationContext); ok && existing.id == operationID {
		return ctx
	}
	return context.WithValue(ctx, operationContextKey{}, operationContext{id: operationID})
}

// RecordWorkRequest checkpoints an accepted asynchronous OCI mutation before
// waiting for it, so the next leader can finish observing it before new writes.
func RecordWorkRequest(ctx context.Context, id string) error {
	operation, _ := ctx.Value(operationContextKey{}).(operationContext)
	if operation.record == nil {
		return nil
	}
	return operation.record(ctx, id)
}

// RetryToken derives a stable OCI token for one request within an operation.
// Step must bind the request's target and payload, so different requests never
// share a token. Direct SDK consumers without an operation retain fresh tokens.
func RetryToken(ctx context.Context, step string) string {
	operation, _ := ctx.Value(operationContextKey{}).(operationContext)
	if operation.id == "" {
		return common.RetryToken()
	}
	sum := sha256.Sum256([]byte(operation.id + "\x00" + step))
	return hex.EncodeToString(sum[:])
}

func New(provider common.ConfigurationProvider, options Options) (*Factory, error) {
	if provider == nil {
		return nil, errors.New("OCI client factory requires a configuration provider")
	}
	if !catalog.IsOCIRegion(options.Region) {
		return nil, fmt.Errorf("OCI client factory region %q is not in the region catalog", options.Region)
	}
	limits := make(map[Service]Limit, len(DefaultLimits))
	for service, limit := range DefaultLimits {
		limits[service] = limit
	}
	for service, limit := range options.Limits {
		if limit.PerSecond <= 0 || limit.Burst < 1 {
			return nil, fmt.Errorf("OCI client limit for %s must be positive", service)
		}
		limits[service] = limit
	}
	return &Factory{provider: provider, region: options.Region, limits: limits,
		policy: RetryPolicy(options.Retry), limiters: map[Service]*rate.Limiter{}}, nil
}

func (f *Factory) Configure(client *common.BaseClient, service Service) {
	limiter := f.Limiter(service)
	previous := client.Interceptor
	client.Interceptor = func(request *http.Request) error {
		ctx := request.Context()
		if ctx == nil {
			ctx = context.Background()
		}
		if err := limiter.Wait(ctx); err != nil {
			return fmt.Errorf("OCI %s rate limiter: %w", service, err)
		}
		if request.Method != http.MethodGet && request.Method != http.MethodHead && request.Method != http.MethodOptions {
			if guard, ok := ctx.Value(authorityKey{}).(func(context.Context) error); ok {
				if err := guard(ctx); err != nil {
					return fmt.Errorf("OCI %s write authority: %w", service, err)
				}
			}
		}
		if previous != nil {
			return previous(request)
		}
		return nil
	}
	policy := f.policy
	// Set only the retry policy: replacing the whole configuration would drop
	// a circuit breaker the SDK installed from OCI_SDK_DEFAULT_CIRCUITBREAKER_ENABLED
	// or its global setting.
	client.Configuration.RetryPolicy = &policy
	ConfigureReadCancellation(client)
}

// PinHost replaces a client's endpoint with an exact canonical endpoint. It is
// used by callers whose signed configuration names the endpoint.
func PinHost(client *common.BaseClient, endpoint string) {
	if endpoint = strings.TrimSuffix(endpoint, "/"); endpoint != "" {
		client.Host = endpoint
	}
}

func (f *Factory) Network() (core.VirtualNetworkClient, error) {
	client, err := core.NewVirtualNetworkClientWithConfigurationProvider(f.provider)
	if err != nil {
		return client, fmt.Errorf("create OCI network client: %w", err)
	}
	client.SetRegion(f.region)
	f.Configure(&client.BaseClient, ServiceNetwork)
	return client, nil
}

func (f *Factory) NetworkLoadBalancer() (networkloadbalancer.NetworkLoadBalancerClient, error) {
	client, err := networkloadbalancer.NewNetworkLoadBalancerClientWithConfigurationProvider(f.provider)
	if err != nil {
		return client, fmt.Errorf("create OCI network load balancer client: %w", err)
	}
	client.SetRegion(f.region)
	f.Configure(&client.BaseClient, ServiceNLB)
	return client, nil
