// LoadBalancer returns a rate-limited flexible (L7) load balancer client. It
// shares the NLB token bucket: both are OCI load balancing.
func (f *Factory) LoadBalancer() (loadbalancer.LoadBalancerClient, error) {
	client, err := loadbalancer.NewLoadBalancerClientWithConfigurationProvider(f.provider)
	if err != nil {
		return client, fmt.Errorf("create OCI load balancer client: %w", err)
	}
	client.SetRegion(f.region)
	f.Configure(&client.BaseClient, ServiceNLB)
	return client, nil
}

// LimitAdmission carries the earliest authenticated expiry through any remaining
// admission waits. The dispatcher checks it again immediately before sending.
func LimitAdmission(ctx context.Context, deadline time.Time) error {
	if deadline.IsZero() || !time.Now().Before(deadline) {
		return errors.New("OCI current admission facts expired")
	}
	if state, ok := ctx.Value(admissionDeadlineKey{}).(*admissionDeadline); ok {
		if state.until.IsZero() || deadline.Before(state.until) {
			state.until = deadline
		}
	}
	return nil
}

// WithAuthority rechecks a durable operation's write authority for every SDK
// mutation attempt, including retries after a lost response or provider error.
// The caller cancels ctx when the claim is lost; reads remain available.
func WithAuthority(ctx context.Context, guard func(context.Context) error) context.Context {
	if guard == nil {
		return ctx
	}
	return context.WithValue(ctx, authorityKey{}, guard)
}

// WithAdmission acquires current write authority for each HTTP mutation attempt
// and holds it until that attempt returns. SDK retries acquire it again.
// Clients must use ConfigureRequestCancellation, as Factory clients do.
func WithAdmission(ctx context.Context, acquire func(context.Context) (func(), error)) context.Context {
	return context.WithValue(ctx, admissionKey{}, acquire)
}

// WithWireAttempt records each dispatch before the final authority admission.
// A missing finish record remains unknown, including after process failure.
func WithWireAttempt(ctx context.Context, begin func(*http.Request) (func(*http.Response, error, bool) error, error)) context.Context {
	return context.WithValue(ctx, wireAttemptKey{}, begin)
}

func (d readDispatcher) Do(request *http.Request) (*http.Response, error) {
	var finish func(*http.Response, error, bool) error
	if request.Method != http.MethodGet && request.Method != http.MethodHead && request.Method != http.MethodOptions {
		deadline := new(admissionDeadline)
		*request = *request.WithContext(context.WithValue(request.Context(), admissionDeadlineKey{}, deadline))
		if begin, ok := request.Context().Value(wireAttemptKey{}).(func(*http.Request) (func(*http.Response, error, bool) error, error)); ok {
			if begin == nil {
				return nil, errors.New("OCI wire attempt journal is unavailable")
			}
			var err error
			finish, err = begin(request)
			if err != nil {
				return nil, fmt.Errorf("OCI wire attempt checkpoint: %w", err)
			}
			if finish == nil {
				return nil, errors.New("OCI wire attempt journal lacks outcome recorder")
			}
		}
		deny := func(err error) (*http.Response, error) {
			if finish != nil {
				err = errors.Join(err, finish(nil, err, false))
			}
			return nil, err
		}
		if finish != nil {
			if err := request.Context().Err(); err != nil {
				return deny(err)
			}
			// The durable begin may block; refresh the claim after that write.
			if guard, ok := request.Context().Value(authorityKey{}).(func(context.Context) error); ok {
				if guard == nil {
					return deny(errors.New("OCI wire authority is unavailable"))
				}
				if err := guard(request.Context()); err != nil {
					return deny(fmt.Errorf("OCI wire authority: %w", err))
				}
			}
		}
		if acquire, ok := request.Context().Value(admissionKey{}).(func(context.Context) (func(), error)); ok {
			if acquire == nil {
				return deny(errors.New("OCI write admission is unavailable"))
			}
			release, err := acquire(request.Context())
			if err != nil {
				return deny(fmt.Errorf("OCI write admission: %w", err))
			}
			if release == nil {
				return deny(errors.New("OCI write admission did not fence current authority"))
			}
			defer release()
		}
		if err := request.Context().Err(); err != nil {
			return deny(err)
		}
		if !deadline.until.IsZero() && !time.Now().Before(deadline.until) {
			return deny(errors.New("OCI current admission facts expired before dispatch"))
		}
	}
	if guard, ok := request.Context().Value(requestGuardKey{}).(func(context.Context) error); ok {
		var err error
		if guard == nil {
			err = errors.New("OCI request session is unavailable")
		} else {
			// Authorization may itself read OCI; those reads must not recurse
			// into the guard they are currently establishing.
			err = guard(context.WithValue(request.Context(), requestGuardKey{}, struct{}{}))
		}
		if err != nil {
			if finish != nil {
				err = errors.Join(err, finish(nil, err, false))
			}
			return nil, &readTransportError{err: err, ctx: request.Context()}
		}
	}
	// The final source guard may wait past a shorter retained admission cap.
	// Recheck it after that wait, immediately before the actual dispatch.
	finalErr := request.Context().Err()
	if deadline, ok := request.Context().Value(admissionDeadlineKey{}).(*admissionDeadline); ok && !deadline.until.IsZero() && !time.Now().Before(deadline.until) {
		finalErr = errors.Join(finalErr, errors.New("OCI original admission deadline expired during final source guard"))
	}
	if finalErr != nil {
		if finish != nil {
			finalErr = errors.Join(finalErr, finish(nil, finalErr, false))
		}
		return nil, &readTransportError{err: finalErr, ctx: request.Context()}
	}
	response, err := d.next.Do(request)
	if finish != nil {
		if recordErr := finish(response, err, true); recordErr != nil {
			if response != nil && response.Body != nil {
				_ = response.Body.Close()
			}
			err = errors.Join(err, fmt.Errorf("OCI wire outcome remains unknown: %w", recordErr))
		}
	}
	if original := originalReadContext(request.Context()); original != nil && err != nil {
		return response, &readTransportError{err: err, ctx: original}
	}
	return response, err

func shouldRetry(response common.OCIOperationResponse, replayable func(*http.Request) bool) bool {
	if ctx := readOperationContext(response); ctx != nil && ctx.Err() != nil {
		return false
	}
	status, request := responseStatus(response)
	if response.Error == nil {
		return false
	}
	if status == 0 {
		if serviceErr, ok := common.IsServiceError(response.Error); ok {
			status = serviceErr.GetHTTPStatusCode()
		}
	}
	if status == http.StatusTooManyRequests {
		return true
	}
	if !replayable(request) {
		return false
	}
	if status >= 500 && status != http.StatusNotImplemented && status < 600 {
		return true
	}
	if status == 0 {
		cause := response.Error
		for {
			failure, ok := errors.AsType[*readTransportError](cause)
			if !ok {
				break
			}
			cause = failure.err
		}
		return common.IsNetworkError(cause) || errors.Is(cause, io.EOF) ||
			errors.Is(cause, io.ErrUnexpectedEOF)
	}
	return false
}

