type providerState struct {
	api          API
	loseResponse bool
	retries      map[string]string
	balancer     LoadBalancer
	backends     []Backend
	calls        []string
	pending      map[string]bool
	finished     map[string]bool
	failWR       bool
	seq          int
	gone         bool
	setGone      bool
	// serving is the serving backend count after every mutation.
	serving []int
	// unhealthy names backends whose health is not OK; healthErr fails
	// the health read.
	unhealthy map[string]bool
	healthErr error
}

func (f *providerState) UnhealthyBackends(context.Context, string, string) (map[string]bool, error) {
	return f.unhealthy, f.healthErr
}

func (f *providerState) GetLoadBalancer(context.Context, string) (LoadBalancer, error) {
	if f.gone {
		return LoadBalancer{}, fmt.Errorf("get OCI load balancer: %w", ociresource.ErrGone)
	}
	return f.balancer, nil
}

func (f *providerState) ListBackends(context.Context, string, string) ([]Backend, error) {
	if f.setGone {
		return nil, fmt.Errorf("list OCI load balancer backends: %w", ociresource.ErrGone)
	}
	return slices.Clone(f.backends), nil
}

// workRequest records a mutation; the next one is refused until the previous
// work request was waited on, as OCI serializes load balancer mutations.
func (f *providerState) workRequest(call string) (string, error) {
	if len(f.pending) > 0 {
		return "", errors.New("load balancer has a mutation in progress")
	}
	f.calls = append(f.calls, call)
	f.seq++
	f.balancer.ETag = fmt.Sprintf("etag-%d", f.seq)
	id := fmt.Sprintf("wr%d", f.seq)
	f.pending = map[string]bool{id: true}
	return id, nil
}

func (f *providerState) countServing() {
	n := 0
	for _, b := range f.backends {
		if !b.Drain && !b.backup && !b.offline {
			n++
		}
	}
	f.serving = append(f.serving, n)
}

func (f *providerState) CreateBackend(_ context.Context, _, _ string, backend Backend) (string, error) {
	id, err := f.workRequest("create " + backend.key() + " " + state(backend))
	if err == nil {
		f.backends = append(f.backends, Backend{IP: backend.IP, Port: backend.Port, Drain: backend.Drain, weight: 1, name: backend.key()})
		f.countServing()
	}
	return id, err
}

func (f *providerState) UpdateBackend(_ context.Context, _, _ string, backend Backend) (string, error) {
	id, err := f.workRequest("update " + backend.Name() + " " + state(backend))
	for i := range f.backends {
		if f.backends[i].Name() == backend.Name() {
			f.backends[i].Drain, f.backends[i].weight, f.backends[i].backup, f.backends[i].offline = backend.Drain, backend.weight, backend.backup, backend.offline
		}
	}
	f.countServing()
	return id, err
}

func (f *providerState) DeleteBackend(_ context.Context, _, _, name string) (string, error) {
	id, err := f.workRequest("delete " + name)
	f.backends = slices.DeleteFunc(f.backends, func(b Backend) bool { return b.Name() == name })
	f.countServing()
	return id, err
}

func (f *providerState) UpdateTags(_ context.Context, _, etag string, tags ociresource.Tags) (string, error) {
	if etag != f.balancer.ETag {
		return "", errors.New("etag mismatch")
	}
	id, err := f.workRequest("tags")
	if err == nil {
		f.balancer.Tags = tags
	}
	return id, err
}

func (f *providerState) WaitWorkRequest(_ context.Context, id string) error {
	if success, ok := f.finished[id]; ok {
		if !success {
			return errors.New("work request FAILED")
		}
		return nil
	}
	if !f.pending[id] {
		return errors.New("unknown work request")
	}
	f.pending = nil
	if f.finished == nil {
		f.finished = map[string]bool{}
	}
	f.finished[id] = !f.failWR
	if f.failWR {
		return errors.New("work request FAILED")
	}
	return nil
}

type allow struct{}

func (allow) Guard(context.Context, uint64) error { return nil }

var (
	key   = ociresource.Key{Region: "GRU", Kind: Kind, Name: "public-terrabase"}
	owner = ociresource.Ownership{Mode: ociresource.TagModeFreeform, Owner: "cell-gru"}
)

func controller(t *testing.T, api *providerState, store ociresource.Store) *ociresource.Controller[Spec, Observed] {
	return &ociresource.Controller[Spec, Observed]{Region: "GRU", Resource: Reconciler{API: api.client(t)}, Store: store,
		Ownership: owner, Authority: allow{}}
}

func observed(ip string, drain bool) Backend {
	return Backend{IP: ip, Port: 9465, Drain: drain, weight: 1, name: ip + ":9465"}
}

func publishAndReconcile(t *testing.T, api *providerState, store ociresource.Store, backends ...Backend) {
	t.Helper()
	confirm(t, api, store)
	spec := Spec{LoadBalancerID: lbID, BackendSet: "terrabase", Backends: backends}
	if _, err := Publish(t.Context(), store, key, ociresource.PolicyEnforce, spec); err != nil {
		t.Fatal(err)
	}
	api.calls = nil
	if result, err := controller(t, api, store).Reconcile(t.Context(), 1); err != nil || result.Failed != 0 {
		t.Fatalf("result=%+v err=%v", result, err)
	}
}

func (f *providerState) client(t *testing.T) API {
	t.Helper()
	if f.api != nil {
		return f.api
	}
	factory, endpoint := ociresourcetest.Server(t, func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		respond := func(value any) {
			body, err := json.Marshal(value)
			if err != nil {
				t.Error(err)
				w.WriteHeader(500)
				return
			}
			_, _ = w.Write(body)
		}
		refuse := func(status int, message string) {
			w.WriteHeader(status)
			respond(map[string]string{"code": "ProviderRefused", "message": message})
		}
		path := r.URL.Path
		name := path[strings.LastIndex(path, "/")+1:]
		if f.gone || (f.setGone && strings.Contains(path, "/backendSets/")) {
			refuse(404, "resource gone")
			return
		}
		if strings.Contains(path, "/workRequests/") || strings.Contains(path, "/loadBalancerWorkRequests/") {
			err := f.WaitWorkRequest(r.Context(), name)
			state := "SUCCEEDED"
			if err != nil {
				state = "FAILED"
			}
			respond(map[string]string{"id": name, "lifecycleState": state, "status": state})
			return
		}
		if r.Method == http.MethodGet {
			switch {
			case strings.HasSuffix(path, "/health"):
				if f.healthErr != nil {
					refuse(412, f.healthErr.Error())
					return
				}
				unhealthy := []string{}
				for name, bad := range f.unhealthy {
					if bad {
						unhealthy = append(unhealthy, name)
					}
				}
				respond(map[string]any{"status": "OK", "criticalStateBackendNames": unhealthy, "warningStateBackendNames": []string{}, "unknownStateBackendNames": []string{}})
			case strings.HasSuffix(path, "/backends"):
				backends := []map[string]any{}
				for _, b := range f.backends {
					backends = append(backends, map[string]any{"ipAddress": b.IP, "port": b.Port, "name": b.Name(), "weight": b.weight, "drain": b.Drain, "backup": b.backup, "offline": b.offline})
				}
				respond(backends)
			default:
				w.Header().Set("etag", f.balancer.ETag)
				respond(map[string]any{"id": f.balancer.ID, "freeformTags": f.balancer.Tags.Freeform, "definedTags": f.balancer.Tags.Defined})
			}
			return
		}
		token := r.Header.Get("opc-retry-token")
		if token != "" && f.retries[token] != "" {
			w.Header().Set("opc-work-request-id", f.retries[token])
			w.WriteHeader(202)
			respond(map[string]any{})
			return
		}
		body, err := io.ReadAll(r.Body)
		if err != nil {
			t.Error(err)
			refuse(400, "body read failed")
			return
		}
		var workRequest string
		switch {
		case r.Method == http.MethodPost && strings.HasSuffix(path, "/backends"):
			var details loadbalancer.CreateBackendDetails
			if err = json.Unmarshal(body, &details); err == nil {
				workRequest, err = f.CreateBackend(r.Context(), lbID, "set", Backend{IP: deref(details.IpAddress), Port: deref(details.Port), Drain: deref(details.Drain), offline: deref(details.Offline), weight: deref(details.Weight), backup: deref(details.Backup)})
			}
		case r.Method == http.MethodPut && strings.Contains(path, "/backends/"):
			var details loadbalancer.UpdateBackendDetails
			if err = json.Unmarshal(body, &details); err == nil {
				workRequest, err = f.UpdateBackend(r.Context(), lbID, "set", Backend{name: name, Drain: deref(details.Drain), offline: deref(details.Offline), weight: deref(details.Weight), backup: deref(details.Backup)})
			}
		case r.Method == http.MethodDelete && strings.Contains(path, "/backends/"):
			workRequest, err = f.DeleteBackend(r.Context(), lbID, "set", name)
		case r.Method == http.MethodPut:
			var details loadbalancer.UpdateLoadBalancerDetails
			if err = json.Unmarshal(body, &details); err == nil {
				workRequest, err = f.UpdateTags(r.Context(), lbID, r.Header.Get("if-match"), ociresource.Tags{Freeform: details.FreeformTags, Defined: details.DefinedTags})
			}
		default:
			t.Errorf("unexpected %s %s", r.Method, path)
			refuse(405, "unexpected operation")
			return
		}
		if err != nil {
			refuse(412, err.Error())
			return
		}
		if token != "" {
			if f.retries == nil {
				f.retries = map[string]string{}
			}
			f.retries[token] = workRequest
		}
		if f.loseResponse {
			f.loseResponse = false
			connection, _, hijackErr := w.(http.Hijacker).Hijack()
			if hijackErr != nil {
				t.Error(hijackErr)
				return
			}
			_ = connection.Close()
			return
		}
		w.Header().Set("opc-work-request-id", workRequest)
		w.WriteHeader(202)
		respond(map[string]any{})
	})
	client, err := factory.LoadBalancer()
	if err != nil {
		t.Fatal(err)
	}
	ociclient.PinHost(&client.BaseClient, endpoint)
	f.api = sdkAPI{client: client, pause: sleep}
	return f.api
}

func persistentStore(t *testing.T) *ociresource.KVStore {
	t.Helper()
	return ociresourcetest.Store(t)
}

func confirm(t *testing.T, api *providerState, store ociresource.Store) {
	t.Helper()
	current, err := store.Get(t.Context(), key)
	if errors.Is(err, ociresource.ErrNotFound) {
		return
	}
	if err != nil {
		t.Fatal(err)
	}
	if current.Operation == nil || !current.Operation.CompletedAt.IsZero() {
		return
	}
	for range 3 {
		result, err := controller(t, api, store).Reconcile(t.Context(), 1)
		if err != nil {
			t.Fatal(err)
		}
		if result.InSync == 1 {
			return
		}
	}
	t.Fatal("operation did not converge")
}

func (s Spec) Validate() error {
	if !strings.HasPrefix(s.LoadBalancerID, "ocid1.loadbalancer.") || s.BackendSet == "" || len(s.BackendSet) > 32 {
		return errors.New("load balancer spec requires a load balancer OCID and backend set name")
	}
	if len(s.Backends) > maxBackends {
		return errors.New("load balancer spec exceeds its backend bound")
	}
	seen := map[string]bool{}
	for _, backend := range s.Backends {
		address, err := netip.ParseAddr(backend.IP)
		if err != nil || !address.Is4() || !address.IsPrivate() {
			return fmt.Errorf("load balancer backend %q is not a private IPv4 address", backend.IP)
		}
		if backend.Port < 1 || backend.Port > 65535 {
			return errors.New("load balancer backend port is out of range")
		}
		if seen[backend.key()] {
			return errors.New("load balancer spec repeats a backend")
		}
		seen[backend.key()] = true
	}
	if !s.serves() && !s.AllowEmpty {
		return errors.New("load balancer spec has no serving backend and does not allow it")
	}
	return nil
}

// serves reports whether any backend is left in rotation.
func (s Spec) serves() bool {
	return slices.ContainsFunc(s.Backends, func(b Backend) bool { return !b.Drain })
}

func (r Reconciler) Observe(ctx context.Context, target ociresource.Target[Spec]) (Observed, bool, error) {
	if err := target.Spec.Validate(); err != nil {
		return Observed{}, false, err
	}
	balancer, err := r.API.GetLoadBalancer(ctx, target.Spec.LoadBalancerID)
	if target.Deleting && errors.Is(err, ociresource.ErrGone) {
		return Observed{}, false, nil
	}
	if err != nil {
		return Observed{}, false, err
	}
	if balancer.ID != target.Spec.LoadBalancerID || !target.Ownership.Owns(target.Key, balancer.Tags) {
		return Observed{}, true, ociresource.ErrForeign
	}
	backends, err := r.API.ListBackends(ctx, target.Spec.LoadBalancerID, target.Spec.BackendSet)
	if target.Deleting && errors.Is(err, ociresource.ErrGone) {
		return Observed{LoadBalancer: balancer}, false, nil
	}
	if err != nil {
		return Observed{}, false, err
	}
	if target.Deleting && len(backends) == 0 {
		return Observed{LoadBalancer: balancer}, false, nil
	}
	return Observed{LoadBalancer: balancer, Backends: backends}, true, nil
}

func (b Backend) serving() bool { return !b.Drain && !b.backup && !b.offline }

// Serving reports an observed backend the load balancer may route to:
// neither drained nor offline. A backup serves too, once the primaries
// fail their health checks.
func (b Backend) Serving() bool { return !b.Drain && !b.offline }

// Fenced returns the backend with drain and offline set and its weight and
// backup kept, for UpdateBackend: a release fence takes a node's backend
// out of rotation and returns it as it was.
func (b Backend) Fenced(drain, offline bool) Backend {
	b.Drain, b.offline = drain, offline
	return b
}

// Shape is an observed backend's weight and backup flag.
func (b Backend) Shape() (weight int, backup bool) { return b.weight, b.backup }

// Shaped returns the backend with weight (zero means 1) and backup.
func (b Backend) Shaped(weight int, backup bool) Backend {
	b.weight, b.backup = weight, backup
	return b
}

func changes(spec Spec, observed []Backend) delta {
	have := map[string]Backend{}
	for _, backend := range observed {
		have[backend.key()] = backend
	}
	want := map[string]bool{}
	var d delta
	for _, backend := range spec.Backends {
		backend.weight, backend.backup, backend.offline, backend.name = defaultWeight, false, false, ""
		want[backend.key()] = true
		current, ok := have[backend.key()]
		switch {
		case !ok:
			d.create = append(d.create, backend)
		case current.Drain == backend.Drain && current.weight == defaultWeight && !current.backup && !current.offline:
		case backend.Drain:
			backend.name = current.name
			d.drain = append(d.drain, backend)
		default:
			backend.name = current.name
			d.undrain = append(d.undrain, backend)
		}
	}
	for _, backend := range observed {
		if !want[backend.key()] {
			d.remove = append(d.remove, backend)
		}
	}
	for _, list := range [][]Backend{d.create, d.undrain, d.drain, d.remove} {
		slices.SortFunc(list, func(a, b Backend) int { return strings.Compare(a.key(), b.key()) })
	}
	return d
}

func state(backend Backend) string {
	if backend.Drain {
		return "drained"
	}
	return "serving"
}

func (Reconciler) Diff(target ociresource.Target[Spec], observed Observed, found bool) ociresource.Plan {
	var plan ociresource.Plan
	if !found {
		plan.Add("blocked", "load balancer %s is not visible", target.Spec.LoadBalancerID)
		return plan
	}
	d := changes(target.Spec, observed.Backends)
	for _, backend := range d.create {
		plan.Add("add-backend", "%s %s", backend.Name(), state(backend))
	}
	for _, backend := range d.undrain {
		plan.Add("serve-backend", "%s", backend.Name())
	}
	for _, backend := range d.drain {
		plan.Add("drain-backend", "%s", backend.Name())
	}
	for _, backend := range d.remove {
		plan.Add("remove-backend", "%s", backend.Name())
	}
	if d.restamp(target, observed.LoadBalancer.Tags) {
		plan.Add("tag", "restamp ownership generation %d", target.Generation)
	}
	return plan
}

func (r Reconciler) checkHealthy(ctx context.Context, spec Spec, observed []Backend) error {
	unhealthy, err := r.API.UnhealthyBackends(ctx, spec.LoadBalancerID, spec.BackendSet)
	if err != nil {
		return fmt.Errorf("read load balancer backend health: %w", err)
	}
	existing := map[string]Backend{}
	for _, backend := range observed {
		existing[backend.key()] = backend
	}
	for _, backend := range spec.Backends {
		current, ok := existing[backend.key()]
		if ok && !backend.Drain && !unhealthy[current.Name()] {
			return nil
		}
	}
	return fmt.Errorf("%w: hold draining or removing a serving backend", ErrNoHealthyBackend)
}

// mutate fences, runs one load balancer mutation and waits for its work
// request.
func (r Reconciler) mutate(ctx context.Context, target ociresource.Target[Spec], call func() (string, error)) error {
	if err := target.Fence(ctx); err != nil {
		return err
	}
	id, err := call()
	if err != nil {
		return err
	}
	if id == "" {
		return errors.New("load balancer mutation returned no work request")
	}
	return r.API.WaitWorkRequest(ctx, id)
}

func (r Reconciler) Apply(ctx context.Context, target ociresource.Target[Spec], observed Observed, found bool, _ ociresource.Plan) error {
	if !found {
		return fmt.Errorf("load balancer %s is not visible; the reconciler never creates load balancers", target.Spec.LoadBalancerID)
	}
	if err := target.Spec.Validate(); err != nil {
		return err
	}
	id, set := target.Spec.LoadBalancerID, target.Spec.BackendSet
	d := changes(target.Spec, observed.Backends)
	update := func(b Backend) (string, error) { return r.API.UpdateBackend(ctx, id, set, b) }
	run := func(verb string, backends []Backend, call func(Backend) (string, error)) error {
		for _, backend := range backends {
			if err := r.mutate(ctx, target, func() (string, error) { return call(backend) }); err != nil {
				return fmt.Errorf("%s load balancer backend %s: %w", verb, backend.Name(), err)
			}
		}
		return nil
	}
	if err := run("add", d.create, func(b Backend) (string, error) { return r.API.CreateBackend(ctx, id, set, b) }); err != nil {
		return err
	}
	if err := run("serve", d.undrain, update); err != nil {
		return err
	}
	// Only a spec that serves nothing (allowed by AllowEmpty) skips the
	// guard: no backend could ever satisfy it.
	if len(d.outOfRotation(observed.Backends)) > 0 && target.Spec.serves() {
		if err := r.checkHealthy(ctx, target.Spec, observed.Backends); err != nil {
			return err
		}
	}
	if err := run("drain", d.drain, update); err != nil {
		return err
	}
	if err := run("remove", d.remove, func(b Backend) (string, error) { return r.API.DeleteBackend(ctx, id, set, b.Name()) }); err != nil {
		return err
	}
	if d.restamp(target, observed.LoadBalancer.Tags) {
		balancer := observed.LoadBalancer
		if !d.empty() {
			// The backend work requests advanced the load balancer's ETag;
			// restamp against a fresh read, and only while it is still owned.
			fresh, err := r.API.GetLoadBalancer(ctx, id)
			if err != nil {
				return fmt.Errorf("re-read load balancer before restamp: %w", err)
			}
			if fresh.ID != id || !target.Ownership.Owns(target.Key, fresh.Tags) {
				return ociresource.ErrForeign
			}
			balancer = fresh
		}
		tags := balancer.Tags.Merge(target.Ownership.Stamp(target.Key, target.Generation, target.SpecDigest))
		if err := r.mutate(ctx, target, func() (string, error) { return r.API.UpdateTags(ctx, id, balancer.ETag, tags) }); err != nil {
			return fmt.Errorf("restamp load balancer ownership: %w", err)
		}
	}
	return nil
}

// Delete empties the backend set. The load balancer and backend set are not
// deleted: they hold the cell's public address and listeners.
func (r Reconciler) Delete(ctx context.Context, target ociresource.Target[Spec], observed Observed) error {
	for _, backend := range observed.Backends {
		if err := r.mutate(ctx, target, func() (string, error) {
			return r.API.DeleteBackend(ctx, target.Spec.LoadBalancerID, target.Spec.BackendSet, backend.Name())
		}); err != nil {
			return fmt.Errorf("remove load balancer backend %s: %w", backend.Name(), err)
		}
	}
	return nil
}

// Publish stores spec as the next generation of key when its digest differs
// from the current record, and reports whether it wrote. A spec with no
// serving backend is never published unless it allows it, so the previous
// backend set stays in force.
func Publish(ctx context.Context, store ociresource.Store, key ociresource.Key, policy ociresource.DriftPolicy, spec Spec) (bool, error) {
	if key.Kind != Kind {
		return false, errors.New("load balancer backends must be published under the lb-backends kind")
	}
	return ociresource.Publish(ctx, store, key, policy, spec)
}

// RecoverWorkRequests observes accepted mutations from the previous process
// before this controller computes another cloud diff.
func (r Reconciler) RecoverWorkRequests(ctx context.Context, ids []string) error {
	var failures []error
	for _, id := range ids {
		if err := r.API.WaitWorkRequest(ctx, id); err != nil {
			if !errors.Is(err, ociresource.ErrWorkRequestFailed) {
				return err
			}
			failures = append(failures, err)
		}
	}
	return errors.Join(failures...)
}

func NewSDKAPI(factory *ociclient.Factory) (API, error) {
	client, err := factory.LoadBalancer()
	if err != nil {
		return nil, err
	}
	return sdkAPI{client: client, pause: sleep}, nil
}

func sleep(ctx context.Context, delay time.Duration) error {
	timer := time.NewTimer(delay)
	defer timer.Stop()
	select {
	case <-ctx.Done():
		return ctx.Err()
	case <-timer.C:
		return nil
	}
}

func deref[T any](value *T) T {
	var zero T
	if value == nil {
		return zero
	}
	return *value
}

// gone wraps a 404 as ociresource.ErrGone.
func gone(what string, err error) error {
	if serviceErr, ok := common.IsServiceError(err); ok && serviceErr.GetHTTPStatusCode() == http.StatusNotFound {
		return fmt.Errorf("%s: %w: %w", what, ociresource.ErrGone, err)
	}
	return fmt.Errorf("%s: %w", what, err)
}

func (a sdkAPI) GetLoadBalancer(ctx context.Context, id string) (LoadBalancer, error) {
	response, err := a.client.GetLoadBalancer(ociclient.RequestContext(ctx), loadbalancer.GetLoadBalancerRequest{LoadBalancerId: new(id)})
	if err != nil {
		return LoadBalancer{}, gone("get OCI load balancer", err)
	}
	return LoadBalancer{ID: deref(response.Id), ETag: deref(response.ETag),
		Tags: ociresource.Tags{Freeform: response.FreeformTags, Defined: response.DefinedTags}}, nil
}

// ListBackends returns every backend of the set in one call: unlike the NLB
// API, the L7 ListBackends request takes no page token and its response
// carries no opc-next-page, so there is no later page to follow.
func (a sdkAPI) ListBackends(ctx context.Context, id, backendSet string) ([]Backend, error) {
	response, err := a.client.ListBackends(ociclient.RequestContext(ctx), loadbalancer.ListBackendsRequest{LoadBalancerId: new(id), BackendSetName: new(backendSet)})
	if err != nil {
		return nil, gone("list OCI load balancer backends", err)
	}
	backends := make([]Backend, 0, len(response.Items))
	for _, item := range response.Items {
		backends = append(backends, Backend{IP: deref(item.IpAddress), Port: deref(item.Port), Drain: deref(item.Drain),
			weight: deref(item.Weight), backup: deref(item.Backup), offline: deref(item.Offline), name: deref(item.Name)})
	}
	return backends, nil
}

// UnhealthyBackends reads the set's health summary: every backend it lists
// as warning, critical or unknown.
func (a sdkAPI) UnhealthyBackends(ctx context.Context, id, backendSet string) (map[string]bool, error) {
	response, err := a.client.GetBackendSetHealth(ociclient.RequestContext(ctx), loadbalancer.GetBackendSetHealthRequest{LoadBalancerId: new(id),
		BackendSetName: new(backendSet)})
	if err != nil {
		return nil, gone("get OCI load balancer backend set health", err)
	}
	unhealthy := map[string]bool{}
	for _, name := range slices.Concat(response.WarningStateBackendNames, response.CriticalStateBackendNames, response.UnknownStateBackendNames) {
		unhealthy[name] = true
	}
	return unhealthy, nil
}

func (a sdkAPI) CreateBackend(ctx context.Context, id, backendSet string, backend Backend) (string, error) {
	response, err := a.client.CreateBackend(ociclient.RequestContext(ctx), loadbalancer.CreateBackendRequest{LoadBalancerId: new(id),
		BackendSetName: new(backendSet), OpcRetryToken: new(ociresource.RetryToken(ctx,
			fmt.Sprintf("lb/create/%s/%s/%s/%t/%t", id, backendSet, backend.key(), backend.Drain, backend.offline))),
		CreateBackendDetails: loadbalancer.CreateBackendDetails{IpAddress: new(backend.IP), Port: new(backend.Port),
			Weight: new(defaultWeight), Backup: new(false), Drain: new(backend.Drain), Offline: new(backend.offline)}})
	if err != nil {
		return "", fmt.Errorf("create OCI load balancer backend: %w", err)
	}
	workRequestID := deref(response.OpcWorkRequestId)
	return workRequestID, ociresource.RecordWorkRequest(ctx, workRequestID)
}

// UpdateBackend sets every flag from the backend: weight (zero means 1),
// backup, drain and offline. The reconciler passes its managed shape; a
// release fence passes the observed one with Fenced.
func (a sdkAPI) UpdateBackend(ctx context.Context, id, backendSet string, backend Backend) (string, error) {
	response, err := a.client.UpdateBackend(ociclient.RequestContext(ctx), loadbalancer.UpdateBackendRequest{LoadBalancerId: new(id),
		BackendSetName: new(backendSet), BackendName: new(backend.Name()), OpcRetryToken: new(ociresource.RetryToken(ctx,
			fmt.Sprintf("lb/update/%s/%s/%s/%d/%t/%t/%t", id, backendSet, backend.Name(), cmp.Or(backend.weight, defaultWeight),
				backend.backup, backend.Drain, backend.offline))),
		UpdateBackendDetails: loadbalancer.UpdateBackendDetails{Weight: new(cmp.Or(backend.weight, defaultWeight)),
			Backup: new(backend.backup), Drain: new(backend.Drain), Offline: new(backend.offline)}})
	if err != nil {
		return "", fmt.Errorf("update OCI load balancer backend: %w", err)
	}
	workRequestID := deref(response.OpcWorkRequestId)
	return workRequestID, ociresource.RecordWorkRequest(ctx, workRequestID)
}

func (a sdkAPI) DeleteBackend(ctx context.Context, id, backendSet, name string) (string, error) {
	response, err := a.client.DeleteBackend(ociclient.RequestContext(ctx), loadbalancer.DeleteBackendRequest{LoadBalancerId: new(id),
		BackendSetName: new(backendSet), BackendName: new(name)})
	if err != nil {
		return "", fmt.Errorf("delete OCI load balancer backend: %w", err)
	}
	workRequestID := deref(response.OpcWorkRequestId)
	return workRequestID, ociresource.RecordWorkRequest(ctx, workRequestID)
}

func (a sdkAPI) UpdateTags(ctx context.Context, id, etag string, tags ociresource.Tags) (string, error) {
	request := loadbalancer.UpdateLoadBalancerRequest{LoadBalancerId: new(id),
		UpdateLoadBalancerDetails: loadbalancer.UpdateLoadBalancerDetails{
			FreeformTags: maps.Clone(tags.Freeform), DefinedTags: tags.Defined}}
	if etag != "" {
		request.IfMatch = new(etag)
	}
	response, err := a.client.UpdateLoadBalancer(ociclient.RequestContext(ctx), request)
	if err != nil {
		return "", fmt.Errorf("update OCI load balancer tags: %w", err)
	}
	workRequestID := deref(response.OpcWorkRequestId)
	return workRequestID, ociresource.RecordWorkRequest(ctx, workRequestID)
}

// WaitWorkRequest polls with doubling backoff until the work request ends.
func (a sdkAPI) WaitWorkRequest(ctx context.Context, id string) error {
	ctx, cancel := context.WithTimeout(ctx, workRequestTimeout)
	defer cancel()
	delay := firstWorkRequestPoll
	for {
		response, err := a.client.GetWorkRequest(ociclient.RequestContext(ctx), loadbalancer.GetWorkRequestRequest{WorkRequestId: new(id)})
		if err != nil {
			return fmt.Errorf("get OCI load balancer work request: %w", err)
		}
		switch response.LifecycleState {
		case loadbalancer.WorkRequestLifecycleStateSucceeded:
			return nil
		case loadbalancer.WorkRequestLifecycleStateAccepted, loadbalancer.WorkRequestLifecycleStateInProgress:
		default:
			return fmt.Errorf("%w: OCI load balancer work request %s ended %s: %s", ociresource.ErrWorkRequestFailed, id, response.LifecycleState, deref(response.Message))
		}
		if err := a.pause(ctx, delay); err != nil {
			return fmt.Errorf("OCI load balancer work request %s did not finish: %w", id, err)
		}
		delay = min(delay*2, maxWorkRequestPoll)
	}
}

