func instance(ip, state string) oci.Instance { return oci.Instance{PrivateIP: ip, State: state} }

type fenceAfter struct{ remaining int }

func (f *fenceAfter) Guard(context.Context, uint64) error {
	if f.remaining <= 0 {
		return errors.New("lost leadership")
	}
	f.remaining--
	return nil
}

func (f *providerState) client(t *testing.T) API {
	t.Helper()
	if f.api != nil {
		return f.api
	}
	factory, endpoint := ociresourcetest.Server(t, func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		respond := func(value any) {
			body, err := json.Marshal(value)
			if err != nil {
				t.Error(err)
				w.WriteHeader(500)
				return
			}
			_, _ = w.Write(body)
		}
		refuse := func(status int, message string) {
			w.WriteHeader(status)
			respond(map[string]string{"code": "ProviderRefused", "message": message})
		}
		path := r.URL.Path
		name := path[strings.LastIndex(path, "/")+1:]
		if f.gone || (f.setGone && strings.Contains(path, "/backendSets/")) {
			refuse(404, "resource gone")
			return
		}
		if strings.Contains(path, "/workRequests/") || strings.Contains(path, "/loadBalancerWorkRequests/") {
			if f.holdWorkRequests {
				refuse(400, "work request observation interrupted")
				return
			}
			err := f.WaitWorkRequest(r.Context(), name)
			state := "SUCCEEDED"
			if err != nil {
				state = "FAILED"
			}
			respond(map[string]string{"id": name, "lifecycleState": state, "status": state})
			return
		}
		if r.Method == http.MethodGet {
			switch {
			case strings.HasSuffix(path, "/health"):
				refuse(405, "health not supported")
			case strings.HasSuffix(path, "/backends"):
				backends := []map[string]any{}
				for _, b := range f.backends {
					backends = append(backends, map[string]any{"ipAddress": b.IP, "port": b.Port, "name": b.Name(), "weight": b.Weight})
				}
				respond(map[string]any{"items": backends})
			default:
				w.Header().Set("etag", f.balancer.ETag)
				respond(map[string]any{"id": f.balancer.ID, "freeformTags": f.balancer.Tags.Freeform, "definedTags": f.balancer.Tags.Defined})
			}
			return
		}
		if f.beforeWrite != nil {
			f.beforeWrite(w, r)
			return
		}
		token := r.Header.Get("opc-retry-token")
		if token != "" && f.retries[token] != "" {
			w.Header().Set("opc-work-request-id", f.retries[token])
			w.WriteHeader(202)
			respond(map[string]any{})
			return
		}
		body, err := io.ReadAll(r.Body)
		if err != nil {
			t.Error(err)
			refuse(400, "body read failed")
			return
		}
		var workRequest string
		switch {
		case r.Method == http.MethodPost && strings.HasSuffix(path, "/backends"):
			var details networkloadbalancer.CreateBackendDetails
			if err = json.Unmarshal(body, &details); err == nil {
				workRequest, err = f.CreateBackend(r.Context(), nlbID, "set", Backend{IP: deref(details.IpAddress), Port: intValue(details.Port), Weight: intValue(details.Weight)})
			}
		case r.Method == http.MethodPut && strings.Contains(path, "/backends/"):
			var details networkloadbalancer.UpdateBackendDetails
			if err = json.Unmarshal(body, &details); err == nil {
				workRequest, err = f.UpdateBackend(r.Context(), nlbID, "set", Backend{name: name, Weight: intValue(details.Weight)})
			}
		case r.Method == http.MethodDelete && strings.Contains(path, "/backends/"):
			workRequest, err = f.DeleteBackend(r.Context(), nlbID, "set", name)
		case r.Method == http.MethodPut:
			var details networkloadbalancer.UpdateNetworkLoadBalancerDetails
			if err = json.Unmarshal(body, &details); err == nil {
				workRequest, err = f.UpdateTags(r.Context(), nlbID, r.Header.Get("if-match"), ociresource.Tags{Freeform: details.FreeformTags, Defined: details.DefinedTags})
			}
		default:
			t.Errorf("unexpected %s %s", r.Method, path)
			refuse(405, "unexpected operation")
			return
		}
		if err != nil {
			refuse(412, err.Error())
			return
		}
		if token != "" {
			if f.retries == nil {
				f.retries = map[string]string{}
			}
			f.retries[token] = workRequest
		}
		if f.loseResponse {
			f.loseResponse = false
			connection, _, hijackErr := w.(http.Hijacker).Hijack()
			if hijackErr != nil {
				t.Error(hijackErr)
				return
			}
			_ = connection.Close()
			return
		}
		w.Header().Set("opc-work-request-id", workRequest)
		w.WriteHeader(202)
		respond(map[string]any{})
	})
	client, err := factory.NetworkLoadBalancer()
	if err != nil {
		t.Fatal(err)
	}
	ociclient.PinHost(&client.BaseClient, endpoint)
	f.api = sdkAPI{client: client, pause: sleep}
	return f.api
}

func persistentStore(t *testing.T) *ociresource.KVStore {
	t.Helper()
	return ociresourcetest.Store(t)
}

func confirm(t *testing.T, api *providerState, store ociresource.Store) {
	t.Helper()
	current, err := store.Get(t.Context(), key)
	if errors.Is(err, ociresource.ErrNotFound) {
		return
	}
	if err != nil {
		t.Fatal(err)
	}
	if current.Operation == nil || !current.Operation.CompletedAt.IsZero() {
		return
	}
	for range 2 {
		result, err := controller(t, api, store).Reconcile(t.Context(), 1)
		if err != nil {
			t.Fatal(err)
		}
		if result.InSync == 1 {
			return
		}
	}
	t.Fatal("operation did not converge")
}

func (s Spec) Validate() error {
	if !strings.HasPrefix(s.NLBID, "ocid1.networkloadbalancer.") || s.BackendSet == "" || len(s.BackendSet) > 32 {
		return errors.New("NLB spec requires an NLB OCID and backend set name")
	}
	if len(s.Backends) > maxBackends {
		return errors.New("NLB spec exceeds its backend bound")
	}
	seen := map[string]bool{}
	for _, backend := range s.Backends {
		address, err := netip.ParseAddr(backend.IP)
		if err != nil || !address.Is4() || !address.IsPrivate() {
			return fmt.Errorf("NLB backend %q is not a private IPv4 address", backend.IP)
		}
		if backend.Port < 1 || backend.Port > 65535 || backend.Weight < 0 || backend.Weight > 100 {
			return errors.New("NLB backend port or weight is out of range")
		}
		if seen[backend.key()] {
			return errors.New("NLB spec repeats a backend")
		}
		seen[backend.key()] = true
	}
	if len(s.Backends) == 0 && !s.AllowEmpty {
		return errors.New("NLB spec has no backends and does not allow an empty set")
	}
	return nil
}

func (r Reconciler) Observe(ctx context.Context, target ociresource.Target[Spec]) (Observed, bool, error) {
	if err := target.Spec.Validate(); err != nil {
		return Observed{}, false, err
	}
	balancer, err := r.API.GetLoadBalancer(ctx, target.Spec.NLBID)
	if target.Deleting && errors.Is(err, ociresource.ErrGone) {
		// The NLB and therefore every backend is gone.
		return Observed{}, false, nil
	}
	if err != nil {
		return Observed{}, false, err
	}
	if balancer.ID != target.Spec.NLBID || !target.Ownership.Owns(target.Key, balancer.Tags) {
		return Observed{}, true, ociresource.ErrForeign
	}
	backends, err := r.API.ListBackends(ctx, target.Spec.NLBID, target.Spec.BackendSet)
	if target.Deleting && errors.Is(err, ociresource.ErrGone) {
		// The backend set is gone; there is nothing left to drain.
		return Observed{LoadBalancer: balancer}, false, nil
	}
	if err != nil {
		return Observed{}, false, err
	}
	if target.Deleting && len(backends) == 0 {
		return Observed{LoadBalancer: balancer}, false, nil
	}
	return Observed{LoadBalancer: balancer, Backends: backends}, true, nil
}

type delta struct {
	create, update, remove []Backend
}

func changes(spec Spec, observed []Backend) delta {
	have := map[string]Backend{}
	for _, backend := range observed {
		have[backend.key()] = backend
	}
	want := map[string]bool{}
	var d delta
	for _, backend := range spec.Backends {
		want[backend.key()] = true
		current, ok := have[backend.key()]
		switch {
		case !ok:
			d.create = append(d.create, backend)
		case current.weight() != backend.weight():
			backend.name = current.name
			d.update = append(d.update, backend)
		}
	}
	for _, backend := range observed {
		if !want[backend.key()] {
			d.remove = append(d.remove, backend)
		}
	}
	for _, list := range [][]Backend{d.create, d.update, d.remove} {
		slices.SortFunc(list, func(a, b Backend) int { return strings.Compare(a.key(), b.key()) })
	}
	return d
}

func (Reconciler) Diff(target ociresource.Target[Spec], observed Observed, found bool) ociresource.Plan {
	var plan ociresource.Plan
	if !found {
		plan.Add("blocked", "NLB %s is not visible", target.Spec.NLBID)
		return plan
	}
	d := changes(target.Spec, observed.Backends)
	for _, backend := range d.create {
		plan.Add("add-backend", "%s weight %d", backend.Name(), backend.weight())
	}
	for _, backend := range d.update {
		plan.Add("reweight-backend", "%s weight %d", backend.Name(), backend.weight())
	}
	for _, backend := range d.remove {
		plan.Add("remove-backend", "%s", backend.Name())
	}
	if target.Ownership.Stale(observed.LoadBalancer.Tags, target.Generation, target.SpecDigest) {
		plan.Add("tag", "restamp ownership generation %d", target.Generation)
	}
	return plan
}

// mutate fences, runs one NLB mutation and waits for its work request.
func (r Reconciler) mutate(ctx context.Context, target ociresource.Target[Spec], call func() (string, error)) error {
	if err := target.Fence(ctx); err != nil {
		return err
	}
	id, err := call()
	return r.wait(ctx, id, err)
}

func (r Reconciler) wait(ctx context.Context, workRequest string, err error) error {
	if err != nil {
		return err
	}
	if workRequest == "" {
		return errors.New("NLB mutation returned no work request")
	}
	return r.API.WaitWorkRequest(ctx, workRequest)
}

func (r Reconciler) Apply(ctx context.Context, target ociresource.Target[Spec], observed Observed, found bool, _ ociresource.Plan) error {
	if !found {
		return fmt.Errorf("NLB %s is not visible; the reconciler never creates load balancers", target.Spec.NLBID)
	}
	if err := target.Spec.Validate(); err != nil {
		return err
	}
	spec, set := target.Spec, target.Spec.BackendSet
	d := changes(spec, observed.Backends)
	// Add and reweight before removing so capacity never dips below the
	// intersection of the old and new sets.
	for _, backend := range d.create {
		if err := r.mutate(ctx, target, func() (string, error) { return r.API.CreateBackend(ctx, spec.NLBID, set, backend) }); err != nil {
			return fmt.Errorf("add NLB backend %s: %w", backend.Name(), err)
		}
	}
	for _, backend := range d.update {
		if err := r.mutate(ctx, target, func() (string, error) { return r.API.UpdateBackend(ctx, spec.NLBID, set, backend) }); err != nil {
			return fmt.Errorf("reweight NLB backend %s: %w", backend.Name(), err)
		}
	}
	for _, backend := range d.remove {
		if err := r.mutate(ctx, target, func() (string, error) { return r.API.DeleteBackend(ctx, spec.NLBID, set, backend.Name()) }); err != nil {
			return fmt.Errorf("remove NLB backend %s: %w", backend.Name(), err)
		}
	}
	if target.Ownership.Stale(observed.LoadBalancer.Tags, target.Generation, target.SpecDigest) {
		balancer := observed.LoadBalancer
		if len(d.create)+len(d.update)+len(d.remove) > 0 {
			// The backend work requests advanced the NLB's ETag; restamp
			// against a fresh read, and only while it is still owned.
			fresh, err := r.API.GetLoadBalancer(ctx, spec.NLBID)
			if err != nil {
				return fmt.Errorf("re-read NLB before restamp: %w", err)
			}
			if fresh.ID != spec.NLBID || !target.Ownership.Owns(target.Key, fresh.Tags) {
				return ociresource.ErrForeign
			}
			balancer = fresh
		}
		tags := balancer.Tags.Merge(target.Ownership.Stamp(target.Key, target.Generation, target.SpecDigest))
		if err := r.mutate(ctx, target, func() (string, error) { return r.API.UpdateTags(ctx, spec.NLBID, balancer.ETag, tags) }); err != nil {
			return fmt.Errorf("restamp NLB ownership: %w", err)
		}
	}
	return nil
}

// Delete drains the backend set. The NLB and backend set are not deleted:
// they hold the region's reserved public IP.
func (r Reconciler) Delete(ctx context.Context, target ociresource.Target[Spec], observed Observed) error {
	for _, backend := range observed.Backends {
		if err := r.mutate(ctx, target, func() (string, error) {
			return r.API.DeleteBackend(ctx, target.Spec.NLBID, target.Spec.BackendSet, backend.Name())
		}); err != nil {
			return fmt.Errorf("remove NLB backend %s: %w", backend.Name(), err)
		}
	}
	return nil
}

// FromPlacement derives the desired backend set from the member hosts the
// fleet currently observes. Only RUNNING hosts with a verified private IP are
// backends; the order of instances does not affect the result.
func FromPlacement(nlbID, backendSet string, port int, instances []oci.Instance) Spec {
	spec := Spec{NLBID: nlbID, BackendSet: backendSet}
	for _, instance := range instances {
		if instance.State != "RUNNING" || instance.PrivateIP == "" {
			continue
		}
		spec.Backends = append(spec.Backends, Backend{IP: instance.PrivateIP, Port: port})
	}
	slices.SortFunc(spec.Backends, func(a, b Backend) int { return strings.Compare(a.key(), b.key()) })
	spec.Backends = slices.CompactFunc(spec.Backends, func(a, b Backend) bool { return a.key() == b.key() })
	return spec
}

// Publish stores spec as the next generation of key when its digest differs
// from the current record. It returns whether a new generation was written.
// An empty placement observation is never published unless the spec allows
// it, so the previous backend set stays in force.
func Publish(ctx context.Context, store ociresource.Store, key ociresource.Key, policy ociresource.DriftPolicy, spec Spec) (bool, error) {
	if key.Kind != Kind {
		return false, errors.New("NLB backends must be published under the nlb-backends kind")
	}
	return ociresource.Publish(ctx, store, key, policy, spec)
}

// RecoverWorkRequests observes accepted mutations from the previous process
// before this controller computes another cloud diff.
func (r Reconciler) RecoverWorkRequests(ctx context.Context, ids []string) error {
	var failures []error
	for _, id := range ids {
		if err := r.API.WaitWorkRequest(ctx, id); err != nil {
			if !errors.Is(err, ociresource.ErrWorkRequestFailed) {
				return err
			}
			failures = append(failures, err)
		}
	}
	return errors.Join(failures...)
}

func NewSDKAPI(factory *ociclient.Factory) (API, error) {
	client, err := factory.NetworkLoadBalancer()
	if err != nil {
		return nil, err
	}
	return sdkAPI{client: client, pause: sleep}, nil
}

func sleep(ctx context.Context, delay time.Duration) error {
	timer := time.NewTimer(delay)
	defer timer.Stop()
	select {
	case <-ctx.Done():
		return ctx.Err()
	case <-timer.C:
		return nil
	}
}

func deref(value *string) string {
	if value == nil {
		return ""
	}
	return *value
}

func (a sdkAPI) GetLoadBalancer(ctx context.Context, id string) (LoadBalancer, error) {
	response, err := a.client.GetNetworkLoadBalancer(ociclient.RequestContext(ctx), networkloadbalancer.GetNetworkLoadBalancerRequest{NetworkLoadBalancerId: new(id)})
	if err != nil {
		if serviceErr, ok := common.IsServiceError(err); ok && serviceErr.GetHTTPStatusCode() == http.StatusNotFound {
			return LoadBalancer{}, fmt.Errorf("get OCI NLB: %w: %w", ociresource.ErrGone, err)
		}
		return LoadBalancer{}, fmt.Errorf("get OCI NLB: %w", err)
	}
	return LoadBalancer{ID: deref(response.Id), ETag: deref(response.Etag),
		Tags: ociresource.Tags{Freeform: response.FreeformTags, Defined: response.DefinedTags}}, nil
}

func (a sdkAPI) ListBackends(ctx context.Context, id, backendSet string) ([]Backend, error) {
	var backends []Backend
	var page *string
	for range maxPages {
		response, err := a.client.ListBackends(ociclient.RequestContext(ctx), networkloadbalancer.ListBackendsRequest{NetworkLoadBalancerId: new(id),
			BackendSetName: new(backendSet), Page: page})
		if err != nil {
			if serviceErr, ok := common.IsServiceError(err); ok && serviceErr.GetHTTPStatusCode() == http.StatusNotFound {
				return nil, fmt.Errorf("list OCI NLB backends: %w: %w", ociresource.ErrGone, err)
			}
			return nil, fmt.Errorf("list OCI NLB backends: %w", err)
		}
		for _, item := range response.Items {
			if item.TargetId != nil && *item.TargetId != "" {
				// Instance-targeted backends are not modeled; surface them as
				// an unmatched name so an enforce pass replaces them by IP.
				backends = append(backends, Backend{IP: "target:" + *item.TargetId, Port: intValue(item.Port), name: deref(item.Name)})
				continue
			}
			backends = append(backends, Backend{IP: deref(item.IpAddress), Port: intValue(item.Port), Weight: intValue(item.Weight),
				name: deref(item.Name)})
		}
		if response.OpcNextPage == nil || *response.OpcNextPage == "" {
			return backends, nil
		}
		page = response.OpcNextPage
	}
	return nil, errors.New("OCI NLB backend list exceeds its page bound")
}

func intValue(value *int) int {
	if value == nil {
		return 0
	}
	return *value
}

func (a sdkAPI) CreateBackend(ctx context.Context, id, backendSet string, backend Backend) (string, error) {
	response, err := a.client.CreateBackend(ociclient.RequestContext(ctx), networkloadbalancer.CreateBackendRequest{NetworkLoadBalancerId: new(id),
		BackendSetName: new(backendSet), OpcRetryToken: new(ociresource.RetryToken(ctx,
			fmt.Sprintf("nlb/create/%s/%s/%s/%d", id, backendSet, backend.key(), backend.weight()))),
		CreateBackendDetails: networkloadbalancer.CreateBackendDetails{IpAddress: new(backend.IP), Port: new(backend.Port),
			Name: new(backend.key()), Weight: new(backend.weight())}})
	if err != nil {
		return "", fmt.Errorf("create OCI NLB backend: %w", err)
	}
	workRequestID := deref(response.OpcWorkRequestId)
	return workRequestID, ociresource.RecordWorkRequest(ctx, workRequestID)
}

func (a sdkAPI) UpdateBackend(ctx context.Context, id, backendSet string, backend Backend) (string, error) {
	response, err := a.client.UpdateBackend(ociclient.RequestContext(ctx), networkloadbalancer.UpdateBackendRequest{NetworkLoadBalancerId: new(id),
		BackendSetName: new(backendSet), BackendName: new(backend.Name()), OpcRetryToken: new(ociresource.RetryToken(ctx,
			fmt.Sprintf("nlb/update/%s/%s/%s/%d", id, backendSet, backend.Name(), backend.weight()))),
		UpdateBackendDetails: networkloadbalancer.UpdateBackendDetails{Weight: new(backend.weight())}})
	if err != nil {
		return "", fmt.Errorf("update OCI NLB backend: %w", err)
	}
	workRequestID := deref(response.OpcWorkRequestId)
	return workRequestID, ociresource.RecordWorkRequest(ctx, workRequestID)
}

func (a sdkAPI) DeleteBackend(ctx context.Context, id, backendSet, name string) (string, error) {
	response, err := a.client.DeleteBackend(ociclient.RequestContext(ctx), networkloadbalancer.DeleteBackendRequest{NetworkLoadBalancerId: new(id),
		BackendSetName: new(backendSet), BackendName: new(name)})
	if err != nil {
		return "", fmt.Errorf("delete OCI NLB backend: %w", err)
	}
	workRequestID := deref(response.OpcWorkRequestId)
	return workRequestID, ociresource.RecordWorkRequest(ctx, workRequestID)
}

func (a sdkAPI) UpdateTags(ctx context.Context, id, etag string, tags ociresource.Tags) (string, error) {
	request := networkloadbalancer.UpdateNetworkLoadBalancerRequest{NetworkLoadBalancerId: new(id),
		UpdateNetworkLoadBalancerDetails: networkloadbalancer.UpdateNetworkLoadBalancerDetails{
			FreeformTags: maps.Clone(tags.Freeform), DefinedTags: tags.Defined}}
	if etag != "" {
		request.IfMatch = new(etag)
	}
	response, err := a.client.UpdateNetworkLoadBalancer(ociclient.RequestContext(ctx), request)
	if err != nil {
		return "", fmt.Errorf("update OCI NLB tags: %w", err)
	}
	workRequestID := deref(response.OpcWorkRequestId)
	return workRequestID, ociresource.RecordWorkRequest(ctx, workRequestID)
}

// WaitWorkRequest polls with doubling backoff until the work request ends.
func (a sdkAPI) WaitWorkRequest(ctx context.Context, id string) error {
	ctx, cancel := context.WithTimeout(ctx, workRequestTimeout)
	defer cancel()
	delay := firstWorkRequestPoll
	for {
		response, err := a.client.GetWorkRequest(ociclient.RequestContext(ctx), networkloadbalancer.GetWorkRequestRequest{WorkRequestId: new(id)})
		if err != nil {
			return fmt.Errorf("get OCI NLB work request: %w", err)
		}
		switch response.Status {
		case networkloadbalancer.OperationStatusSucceeded:
			return nil
		case networkloadbalancer.OperationStatusAccepted, networkloadbalancer.OperationStatusInProgress:
		default:
			return fmt.Errorf("%w: OCI NLB work request %s ended %s", ociresource.ErrWorkRequestFailed, id, response.Status)
		}
		if err := a.pause(ctx, delay); err != nil {
			return fmt.Errorf("OCI NLB work request %s did not finish: %w", id, err)
		}
		delay = min(delay*2, maxWorkRequestPoll)
	}
}

func (f TLSFiles) complete() bool {
	return f.CAFile != "" && f.CertFile != "" && f.KeyFile != ""
}

// Embedded configures the in-process regional NATS and JetStream server.
// Routes are stable seed addresses; NATS route discovery connects the remaining
// members once any seed is reachable. A persisted StoreDir is required.
type Embedded struct {
	Host                  string      `json:"host"`
	Port                  int         `json:"port"`
	RouteHost             string      `json:"route_host"`
	RoutePort             int         `json:"route_port"`
	Routes                []string    `json:"routes"`
	StoreDir              string      `json:"store_dir"`
	StoreMaxBytes         int64       `json:"store_max_bytes,omitzero"`
	TLS                   TLSFiles    `json:"tls"`
	RouteTLS              TLSFiles    `json:"route_tls"`
	Users                 []NKeyGrant `json:"users"`
	RouteUser             string      `json:"route_user"`
	RoutePasswordFile     string      `json:"route_password_file"`
	OperatorJWTFile       string      `json:"operator_jwt_file,omitempty"`
	SystemJWTFile         string      `json:"system_jwt_file,omitempty"`
	CellJWTFile           string      `json:"cell_jwt_file,omitempty"`
	SystemCredentialsFile string      `json:"system_credentials_file,omitempty"`
	// MembershipCredentialsFile is an optional system-account user limited to
	// metadata peer remove and leader step-down; see OpenMembershipAdmin.
	MembershipCredentialsFile string   `json:"membership_credentials_file,omitempty"`
	TicketPublicKeyFile       string   `json:"ticket_public_key_file,omitempty"`
	BrokerIDs                 []string `json:"broker_ids,omitempty"`
	// InterRegion describes this region's reviewed leaf topology and credentials.
	// An absent block describes an isolated cell.
	InterRegion *InterRegion `json:"interregion,omitempty"`
	// Link joins this region to the global home with one link signer. It
	// replaces InterRegion; a configuration sets one or the other.
	Link *Link `json:"link,omitempty"`
}

// Config describes a single regional cell. Every connection requires verified
// TLS and a JWT credential scoped to its regional account.
type Config struct {
	Cell            string    `json:"cell"`
	Instance        string    `json:"instance"`
	Replicas        int       `json:"replicas"`
	ClientRole      string    `json:"client_role,omitempty"`
	URL             string    `json:"url"`
	NKeySeedFile    string    `json:"nkey_seed_file"`
	CredentialsFile string    `json:"credentials_file"`
	TLS             TLSFiles  `json:"tls"`
	Embedded        *Embedded `json:"embedded"`
	// OperatorForward is a transient CLI-only TCP route. Its keys remain the
	// configured controller TLS identities; values are local Bastion forwards.
	OperatorForward map[string]string `json:"-"`
	// ReloadClientMaterial, when set, is consulted on every connect and
	// reconnect so renewed credentials take effect without a process restart.
	// It must keep the startup NATS user key; failures use the startup files.
	ReloadClientMaterial func() (ClientMaterial, error) `json:"-"`
}

func Start(ctx context.Context, cfg Config) (_ *Runtime, err error) {
	return start(ctx, cfg, false)
}

// StartIdentityRekey joins only the existing regional quorum. The caller must
// verify its root checkpoint before opening it and close it after shared reset
// completion before starting normal external transports on the same store.
func StartIdentityRekey(ctx context.Context, cfg Config) (*Runtime, error) {
	if cfg.Embedded == nil {
		return nil, errors.New("identity rekey requires an installed production broker")
	}
	return start(ctx, cfg, true)
}

func start(ctx context.Context, cfg Config, identityRekey bool) (_ *Runtime, err error) {
	if err := cfg.validate(); err != nil {
		return nil, err
	}
	r := &Runtime{cell: cfg.Cell}
	defer func() {
		if err != nil {
			_ = r.Close()
		}
	}()
	if cfg.Embedded != nil {
		options, optionsErr := serverOptionsForStart(cfg, identityRekey)
		if optionsErr != nil {
			return nil, optionsErr
		}
		r.server, err = server.NewServer(options)
		if err != nil {
			return nil, fmt.Errorf("create embedded NATS: %w", err)
		}
		if err := pinNodeIdentity(cfg.Embedded.StoreDir, cfg.Cell, cfg.Instance, r.server.NodeName()); err != nil {
			return nil, fmt.Errorf("pin embedded NATS Raft identity: %w", err)
		}
		r.server.SetLoggerV2(natsLogger{}, false, false, false)
		r.serverName = options.ServerName
		for _, id := range cfg.Embedded.BrokerIDs {
			r.brokerNames = append(r.brokerNames, ServerName(cfg.Cell, id))
		}
		go r.server.Start()
		if !serverReady(ctx, r.server) {
			return nil, errors.New("embedded NATS did not become ready")
		}
		cfg.URL = r.server.ClientURL()
		r.resolver = options.AccountResolver.(*accountResolver)
		r.operator = options.TrustedOperators[0]
		if _, err := r.server.LookupAccount(r.resolver.cell); err != nil {
			return nil, fmt.Errorf("load regional cell account: %w", err)
		}
	}
	options, err := clientOptions(cfg)
	if err != nil {
		return nil, err
	}
	if cfg.Embedded != nil {
		options = append(options, nats.InProcessServer(r.server))
	}

func (cfg Config) validate() error {
	if len(cfg.OperatorForward) != 0 {
		if _, _, err := operatorForwarding(cfg); err != nil {
			return err
		}
	}
	if !cellName.MatchString(cfg.Cell) || !cellName.MatchString(cfg.Instance) {
		return errors.New("cell and instance must be lowercase NATS tokens")
	}
	// Every protocol subject builder refuses the reserved scope as a cell
	// and returns "", which would surface far from here as empty grants.
	if cfg.Cell == protocol.GlobalScope {
		return errors.New("cell name is reserved for the global scope")
	}
	if cfg.Replicas != 1 && cfg.Replicas != 3 && cfg.Replicas != 5 {
		return errors.New("regional replicas must be 1, 3, or 5")
	}
	if cfg.ClientRole != "" && cfg.ClientRole != "controller" && cfg.ClientRole != "operator" && cfg.ClientRole != "host" {
		return errors.New("invalid regional NATS client role")
	}
	if cfg.Embedded == nil && cfg.URL == "" {
		return errors.New("regional NATS URL or embedded server is required")
	}
	if cfg.NKeySeedFile != "" && cfg.CredentialsFile != "" {
		return errors.New("choose one regional NKey seed or JWT credentials file")
	}
	if !cfg.TLS.complete() || cfg.CredentialsFile == "" || cfg.NKeySeedFile != "" {
		return errors.New("regional NATS requires client TLS and JWT credentials")
	}
	if cfg.Embedded != nil && (!cfg.Embedded.TLS.complete() || !cfg.Embedded.RouteTLS.complete() ||
		cfg.Embedded.OperatorJWTFile == "" || cfg.Embedded.SystemJWTFile == "" ||
		cfg.Embedded.CellJWTFile == "" || cfg.Embedded.SystemCredentialsFile == "" ||
		cfg.Embedded.TicketPublicKeyFile == "" || len(cfg.Embedded.BrokerIDs) != cfg.Replicas || len(cfg.Embedded.Users) != 0) {
		return errors.New("production embedded NATS requires operator/system/cell JWTs, system credentials, and client/route TLS")
	}
	if cfg.Embedded != nil {
		e := cfg.Embedded
		if e.InterRegion != nil && e.Link != nil {
			return errors.New("a region links to peers by interregion or by link, not both")
		}
		if err := e.InterRegion.validate(cfg); err != nil {
			return err
		}
		if e.Link != nil {
			if err := e.Link.validate(cfg); err != nil {
				return err
			}
		}
		seen := make(map[string]struct{}, len(e.BrokerIDs))
		for _, id := range e.BrokerIDs {
			if !cellName.MatchString(id) {
				return errors.New("production broker ID is invalid")
			}
			if _, exists := seen[id]; exists {
				return errors.New("production broker IDs must be unique")
			}
			seen[id] = struct{}{}
		}
		if _, own := seen[cfg.Instance]; !own {
			return errors.New("production broker ID list excludes this instance")
		}
		if e.StoreDir == "" || e.Host == "" || e.Port == 0 {
			return errors.New("embedded NATS requires store_dir, host, and port")
		}
		if e.StoreMaxBytes < 0 {
			return errors.New("embedded NATS store_max_bytes must be positive when set")
		}
		if cfg.Replicas > 1 && (e.RouteHost == "" || e.RoutePort == 0 || len(e.Routes) == 0) {
			return errors.New("clustered NATS requires route_host, route_port and at least one seed route")
		}
		if cfg.Replicas > 1 && (e.RouteUser == "" || e.RoutePasswordFile == "") {
			return errors.New("production NATS routes require a route user and password file")
		}
	}
	return nil
}

