type providerState struct {
	group        Group
	rules        []ObservedRule
	nextID       int
	calls        []string
	gone         bool
	api          API
	loseResponse bool
	onRead       func()
}

func (f *providerState) GetGroup(context.Context, string) (Group, error) {
	if f.gone {
		return Group{}, fmt.Errorf("get OCI NSG: %w", ociresource.ErrGone)
	}
	return f.group, nil
}
func (f *providerState) ListRules(context.Context, string) ([]ObservedRule, error) {
	return slices.Clone(f.rules), nil
}
func (f *providerState) AddRules(_ context.Context, _ string, rules []Rule) error {
	f.calls = append(f.calls, fmt.Sprintf("add %d", len(rules)))
	f.group.ETag += "+" // a rule change advances the NSG's ETag, as OCI does
	for _, rule := range rules {
		f.nextID++
		f.rules = append(f.rules, ObservedRule{ID: fmt.Sprintf("r%d", f.nextID), Rule: rule})
	}
	return nil
}
func (f *providerState) RemoveRules(_ context.Context, _ string, ids []string) error {
	f.calls = append(f.calls, fmt.Sprintf("remove %d", len(ids)))
	f.group.ETag += "-"
	f.rules = slices.DeleteFunc(f.rules, func(rule ObservedRule) bool { return slices.Contains(ids, rule.ID) })
	return nil
}
func (f *providerState) UpdateTags(_ context.Context, _, etag string, tags ociresource.Tags) error {
	if etag != f.group.ETag {
		return fmt.Errorf("etag mismatch")
	}
	f.calls = append(f.calls, "tags")
	f.group.Tags, f.group.ETag = tags, etag+"'"
	return nil
}

type allow struct{}

func (allow) Guard(context.Context, uint64) error { return nil }

var key = ociresource.Key{Region: "GRU", Kind: Kind, Name: "controller"}

func owned(owner ociresource.Ownership) Group {
	return Group{ID: nsgID, ETag: "e1", Tags: ociresource.Tags{Freeform: map[string]string{"cost-center": "infra"}}.Merge(owner.Stamp(key, 0, ""))}
}

func https(cidr string) Rule {
	return Rule{Direction: DirectionIngress, Protocol: ProtocolTCP, Peer: cidr, PortMin: 443, PortMax: 443, Description: "public API"}
}

func run(t *testing.T, api *providerState, store ociresource.Store, spec Spec, policy ociresource.DriftPolicy, generation uint64) ociresource.Result {
	t.Helper()
	confirm(t, api, store)
	desired, err := ociresource.NewDesired(key, generation, policy, spec)
	if err != nil {
		t.Fatal(err)
	}
	if current, err := store.Get(t.Context(), key); err != nil || current.SpecDigest != desired.SpecDigest {
		if _, err := store.Put(t.Context(), desired); err != nil {
			t.Fatal(err)
		}
	}
	controller := &ociresource.Controller[Spec, Observed]{Region: "GRU", Resource: Reconciler{API: api.client(t)}, Store: store,
		Ownership: ociresource.Ownership{Mode: ociresource.TagModeFreeform, Owner: "cell-gru"}, Authority: allow{}}
	result, err := controller.Reconcile(t.Context(), 1)
	if err != nil {
		t.Fatal(err)
	}
	return result
}

func (f *providerState) client(t *testing.T) API {
	t.Helper()
	if f.api != nil {
		return f.api
	}
	factory, endpoint := ociresourcetest.Server(t, func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		if r.Method == http.MethodGet && f.onRead != nil {
			hook := f.onRead
			f.onRead = nil
			hook()
		}
		if f.gone {
			w.WriteHeader(404)
			_, _ = io.WriteString(w, `{"code":"NotAuthorizedOrNotFound","message":"NSG not found"}`)
			return
		}
		var err error
		if r.Method != http.MethodGet {
			body, readErr := io.ReadAll(r.Body)
			if readErr != nil {
				t.Error(readErr)
				w.WriteHeader(400)
				return
			}
			switch {
			case strings.HasSuffix(r.URL.Path, "/actions/addSecurityRules"):
				var details core.AddNetworkSecurityGroupSecurityRulesDetails
				if err = json.Unmarshal(body, &details); err == nil {
					if len(details.SecurityRules) > 25 {
						t.Error("provider batch limit exceeded")
					}
					var rules []Rule
					for _, rule := range details.SecurityRules {
						// Both payloads use the same OCI security-rule fields.
						encoded, marshalErr := json.Marshal(rule)
						if marshalErr != nil {
							t.Error(marshalErr)
							return
						}
						var observed core.SecurityRule
						if decodeErr := json.Unmarshal(encoded, &observed); decodeErr != nil {
							t.Error(decodeErr)
							return
						}
						rules = append(rules, normalize(observed))
					}
					err = f.AddRules(r.Context(), nsgID, rules)
				}
			case strings.HasSuffix(r.URL.Path, "/actions/removeSecurityRules"):
				var details core.RemoveNetworkSecurityGroupSecurityRulesDetails
				if err = json.Unmarshal(body, &details); err == nil {
					err = f.RemoveRules(r.Context(), nsgID, details.SecurityRuleIds)
				}
			case r.Method == http.MethodPut:
				var details core.UpdateNetworkSecurityGroupDetails
				if err = json.Unmarshal(body, &details); err == nil {
					err = f.UpdateTags(r.Context(), nsgID, r.Header.Get("if-match"), ociresource.Tags{Freeform: details.FreeformTags, Defined: details.DefinedTags})
				}
			default:
				t.Errorf("unexpected %s %s", r.Method, r.URL.Path)
				w.WriteHeader(405)
				return
			}
			if err != nil {
				w.WriteHeader(412)
				_, _ = io.WriteString(w, `{"code":"NoEtagMatch","message":"mutation refused"}`)
				return
			}
			if f.loseResponse {
				f.loseResponse = false
				connection, _, hijackErr := w.(http.Hijacker).Hijack()
				if hijackErr != nil {
					t.Error(hijackErr)
					return
				}
				_ = connection.Close()
				return
			}
		}
		var response any
		if strings.HasSuffix(r.URL.Path, "/securityRules") {
			rules := []core.SecurityRule{}
			for _, observed := range f.rules {
				encoded, marshalErr := json.Marshal(addDetails(observed.Rule))
				if marshalErr != nil {
					t.Error(marshalErr)
					return
				}
				var rule core.SecurityRule
				if decodeErr := json.Unmarshal(encoded, &rule); decodeErr != nil {
					t.Error(decodeErr)
					return
				}
				rule.Id = new(observed.ID)
				rules = append(rules, rule)
			}
			response = rules
		} else if strings.Contains(r.URL.Path, "/actions/") {
			response = map[string]any{"securityRules": []any{}}
		} else {
			w.Header().Set("etag", f.group.ETag)
			response = core.NetworkSecurityGroup{Id: new(f.group.ID), FreeformTags: f.group.Tags.Freeform, DefinedTags: f.group.Tags.Defined}
		}
		body, marshalErr := json.Marshal(response)
		if marshalErr != nil {
			t.Error(marshalErr)
			w.WriteHeader(500)
			return
		}
		_, _ = w.Write(body)
	})
	network, err := factory.Network()
	if err != nil {
		t.Fatal(err)
	}
	ociclient.PinHost(&network.BaseClient, endpoint)
	f.api = sdkAPI{network: network}
	return f.api
}

func persistentStore(t *testing.T) *ociresource.KVStore {
	t.Helper()
	return ociresourcetest.Store(t)
}

func confirm(t *testing.T, api *providerState, store ociresource.Store) {
	t.Helper()
	current, err := store.Get(t.Context(), key)
	if errors.Is(err, ociresource.ErrNotFound) {
		return
	}
	if err != nil {
		t.Fatal(err)
	}
	if current.Tombstone != nil || current.Operation == nil || !current.Operation.CompletedAt.IsZero() {
		return
	}
	controller := &ociresource.Controller[Spec, Observed]{Region: "GRU", Resource: Reconciler{API: api.client(t)}, Store: store, Ownership: ociresource.Ownership{Mode: ociresource.TagModeFreeform, Owner: "cell-gru"}, Authority: allow{}}
	result, err := controller.Reconcile(t.Context(), 1)
	if err != nil || result.InSync != 1 {
		t.Fatalf("confirm=%+v err=%v", result, err)
	}
}

type Rule struct {
	Direction   string `json:"direction"`
	Protocol    string `json:"protocol"`
	Peer        string `json:"peer"`
	PeerType    string `json:"peerType,omitempty"`
	PortMin     int    `json:"portMin,omitempty"`
	PortMax     int    `json:"portMax,omitempty"`
	Stateless   bool   `json:"stateless,omitempty"`
	Description string `json:"description,omitempty"`
	// unsupported marks an observed rule using features Rule does not model.
	unsupported bool
}

func (r Rule) peerType() string { return cmp.Or(r.PeerType, PeerCIDR) }

// EffectivePeerType is the peer type with the CIDR_BLOCK default applied.
func (r Rule) EffectivePeerType() string { return r.peerType() }

// identity is the rule's semantic tuple; descriptions do not affect matching.
func (r Rule) identity() string {
	return fmt.Sprintf("%s|%s|%s|%s|%d-%d|%t|%t", r.Direction, r.Protocol, r.peerType(), r.Peer, r.PortMin, r.PortMax,
		r.Stateless, r.unsupported)
}

// Identity is the rule's semantic tuple. The security-list reconciler models
// the same rule shape and matches rules by it.
func (r Rule) Identity() string { return r.identity() }

// MarkUnsupported returns the rule flagged as using OCI features Rule does
// not model (source ports, ICMP filters), so it never matches a desired rule.
func (r Rule) MarkUnsupported() Rule {
	r.unsupported = true
	return r
}

// Validate checks one rule in isolation.
func (r Rule) Validate() error { return r.validate() }

func (r Rule) validate() error {
	if r.Direction != DirectionIngress && r.Direction != DirectionEgress {
		return errors.New("NSG rule direction must be INGRESS or EGRESS")
	}
	switch r.Protocol {
	case ProtocolAll, ProtocolICMP:
		if r.PortMin != 0 || r.PortMax != 0 {
			return errors.New("NSG rule ports require TCP or UDP")
		}
	case ProtocolTCP, ProtocolUDP:
		if (r.PortMin == 0) != (r.PortMax == 0) || r.PortMin < 0 || r.PortMax > 65535 || r.PortMin > r.PortMax {
			return errors.New("NSG rule port range is invalid")
		}
	default:
		return fmt.Errorf("NSG rule protocol %q is unsupported", r.Protocol)
	}
	switch r.peerType() {
	case PeerCIDR:
		prefix, err := netip.ParsePrefix(r.Peer)
		if err != nil {
			return fmt.Errorf("NSG rule CIDR %q is invalid", r.Peer)
		}
		// OCI stores the masked network; a CIDR with host bits set would
		// never match the stored rule and be re-added on every pass.
		if canonical := prefix.Masked().String(); canonical != r.Peer {
			return fmt.Errorf("NSG rule CIDR %q is not canonical; use %q", r.Peer, canonical)
		}
	case PeerNSG:
		if !strings.HasPrefix(r.Peer, "ocid1.networksecuritygroup.") {
			return errors.New("NSG rule peer is not an NSG OCID")
		}
	case PeerService:
		if r.Peer == "" {
			return errors.New("NSG rule service peer is empty")
		}
	default:
		return fmt.Errorf("NSG rule peer type %q is unsupported", r.PeerType)
	}
	if len(r.Description) > 128 {
		return errors.New("NSG rule description is too long")
	}
	return nil
}

// Spec is the desired rule set of one NSG.
type Spec struct {
	NSGID     string `json:"nsgId"`
	Rules     []Rule `json:"rules"`
	Exclusive bool   `json:"exclusive,omitempty"`
}

// Validate rejects malformed or duplicated rules.
func (s Spec) Validate() error {
	if !strings.HasPrefix(s.NSGID, "ocid1.networksecuritygroup.") {
		return errors.New("NSG spec requires an NSG OCID")
	}
	if len(s.Rules) > maxRulesPerNSG {
		return fmt.Errorf("NSG spec has %d rules, more than OCI's %d per NSG", len(s.Rules), maxRulesPerNSG)
	}
	seen := map[string]bool{}
	for _, rule := range s.Rules {
		if err := rule.validate(); err != nil {
			return err
		}
		if seen[rule.identity()] {
			return errors.New("NSG spec repeats a rule")
		}
		seen[rule.identity()] = true
	}
	return nil
}

func marker(key ociresource.Key) string { return "terrascale/" + key.Name + ":" }

func managedDescription(key ociresource.Key, rule Rule) string {
	return strings.TrimSpace(marker(key) + " " + rule.Description)
}

func (r Reconciler) Observe(ctx context.Context, target ociresource.Target[Spec]) (Observed, bool, error) {
	if err := target.Spec.Validate(); err != nil {
		return Observed{}, false, err
	}
	group, err := r.API.GetGroup(ctx, target.Spec.NSGID)
	if target.Deleting && errors.Is(err, ociresource.ErrGone) {
		// The NSG and therefore every managed rule is gone.
		return Observed{}, false, nil
	}
	if err != nil {
		return Observed{}, false, err
	}
	if group.ID != target.Spec.NSGID || !target.Ownership.Owns(target.Key, group.Tags) {
		return Observed{}, true, ociresource.ErrForeign
	}
	rules, err := r.API.ListRules(ctx, target.Spec.NSGID)
	if err != nil {
		return Observed{}, false, err
	}
	if target.Deleting && !slices.ContainsFunc(rules, func(rule ObservedRule) bool { return deletable(target, rule) }) {
		return Observed{Group: group}, false, nil
	}
	return Observed{Group: group, Rules: rules}, true, nil
}

// deletable reports a rule a tombstoned spec removes: every rule carrying its
// marker, and under an exclusive spec also an unmarked rule the spec itself
// asked for (kept unmarked because it already existed when enforced). Rules
// the spec never named are left alone even in exclusive mode: a deletion
// relinquishes management and must not strip an NSG that member VNICs use.
func deletable(target ociresource.Target[Spec], rule ObservedRule) bool {
	if strings.HasPrefix(rule.Rule.Description, marker(target.Key)) {
		return true
	}
	return target.Spec.Exclusive && slices.ContainsFunc(target.Spec.Rules, func(wanted Rule) bool {
		return wanted.identity() == rule.Rule.identity()
	})
}

// changes computes rules to add and rule IDs to remove.
func changes(target ociresource.Target[Spec], observed Observed) (add []Rule, remove []ObservedRule) {
	want := map[string]Rule{}
	for _, rule := range target.Spec.Rules {
		want[rule.identity()] = rule
	}
	have := map[string]bool{}
	for _, existing := range observed.Rules {
		managed := target.Spec.Exclusive || strings.HasPrefix(existing.Rule.Description, marker(target.Key))
		identity := existing.Rule.identity()
		if _, wanted := want[identity]; wanted && !have[identity] {
			have[identity] = true
			continue
		}
		if managed {
			remove = append(remove, existing)
		}
	}
	for _, rule := range target.Spec.Rules {
		if !have[rule.identity()] {
			add = append(add, rule)
		}
	}
	slices.SortFunc(add, func(a, b Rule) int { return strings.Compare(a.identity(), b.identity()) })
	slices.SortFunc(remove, func(a, b ObservedRule) int { return strings.Compare(a.ID, b.ID) })
	return add, remove
}

func (Reconciler) Diff(target ociresource.Target[Spec], observed Observed, found bool) ociresource.Plan {
	var plan ociresource.Plan
	if !found {
		plan.Add("blocked", "NSG %s is not visible", target.Spec.NSGID)
		return plan
	}
	add, remove := changes(target, observed)
	for _, rule := range add {
		plan.Add("add-rule", "%s", rule.identity())
	}
	for _, rule := range remove {
		plan.Add("remove-rule", "%s %s", rule.ID, rule.Rule.identity())
	}
	if target.Ownership.Stale(observed.Group.Tags, target.Generation, target.SpecDigest) {
		plan.Add("tag", "restamp ownership generation %d", target.Generation)
	}
	return plan
}

func (r Reconciler) Apply(ctx context.Context, target ociresource.Target[Spec], observed Observed, found bool, _ ociresource.Plan) error {
	if !found {
		return fmt.Errorf("NSG %s is not visible; the reconciler never creates NSGs", target.Spec.NSGID)
	}
	add, remove := changes(target, observed)
	// Add before remove so a rule whose description changed never leaves a
	// window without the permission.
	for chunk := range slices.Chunk(add, maxRulesPerCall) {
		marked := make([]Rule, 0, len(chunk))
		for _, rule := range chunk {
			rule.Description = managedDescription(target.Key, rule)
			marked = append(marked, rule)
		}
		if err := target.Fence(ctx); err != nil {
			return err
		}
		if err := r.API.AddRules(ctx, target.Spec.NSGID, marked); err != nil {
			return fmt.Errorf("add NSG rules: %w", err)
		}
	}
	for chunk := range slices.Chunk(remove, maxRulesPerCall) {
		ids := make([]string, 0, len(chunk))
		for _, rule := range chunk {
			ids = append(ids, rule.ID)
		}
		if err := target.Fence(ctx); err != nil {
			return err
		}
		if err := r.API.RemoveRules(ctx, target.Spec.NSGID, ids); err != nil {
			return fmt.Errorf("remove NSG rules: %w", err)
		}
	}
	if target.Ownership.Stale(observed.Group.Tags, target.Generation, target.SpecDigest) {
		group := observed.Group
		if len(add)+len(remove) > 0 {
			// The rule changes advanced the NSG's ETag; restamp against a
			// fresh read, and only while it is still owned.
			fresh, err := r.API.GetGroup(ctx, target.Spec.NSGID)
			if err != nil {
				return fmt.Errorf("re-read NSG before restamp: %w", err)
			}
			if fresh.ID != target.Spec.NSGID || !target.Ownership.Owns(target.Key, fresh.Tags) {
				return ociresource.ErrForeign
			}
			group = fresh
		}
		tags := group.Tags.Merge(target.Ownership.Stamp(target.Key, target.Generation, target.SpecDigest))
		if err := target.Fence(ctx); err != nil {
			return err
		}
		if err := r.API.UpdateTags(ctx, target.Spec.NSGID, group.ETag, tags); err != nil {
			return fmt.Errorf("restamp NSG ownership: %w", err)
		}
	}
	return nil
}

// Delete removes the reconciler's rules. The NSG itself is not deleted: it is
// referenced by member host VNICs and owned by the region foundation.
func (r Reconciler) Delete(ctx context.Context, target ociresource.Target[Spec], observed Observed) error {
	var ids []string
	for _, rule := range observed.Rules {
		if deletable(target, rule) {
			ids = append(ids, rule.ID)
		}
	}
	for chunk := range slices.Chunk(ids, maxRulesPerCall) {
		if err := target.Fence(ctx); err != nil {
			return err
		}
		if err := r.API.RemoveRules(ctx, target.Spec.NSGID, chunk); err != nil {
			return fmt.Errorf("remove NSG rules: %w", err)
		}
	}
	return nil
}

func NewSDKAPI(factory *ociclient.Factory) (API, error) {
	network, err := factory.Network()
	if err != nil {
		return nil, err
	}
	return sdkAPI{network: network}, nil
}

func deref(value *string) string {
	if value == nil {
		return ""
	}
	return *value
}

func (a sdkAPI) GetGroup(ctx context.Context, id string) (Group, error) {
	response, err := a.network.GetNetworkSecurityGroup(ociclient.RequestContext(ctx), core.GetNetworkSecurityGroupRequest{NetworkSecurityGroupId: new(id)})
	if err != nil {
		if serviceErr, ok := common.IsServiceError(err); ok && serviceErr.GetHTTPStatusCode() == http.StatusNotFound {
			return Group{}, fmt.Errorf("get OCI NSG: %w: %w", ociresource.ErrGone, err)
		}
		return Group{}, fmt.Errorf("get OCI NSG: %w", err)
	}
	return Group{ID: deref(response.Id), ETag: deref(response.Etag),
		Tags: ociresource.Tags{Freeform: response.FreeformTags, Defined: response.DefinedTags}}, nil
}

// PortRange extracts the destination port range of TCP or UDP options. ok is
// false when a source port range is set, which Rule does not model.
func PortRange(options *core.TcpOptions, udp *core.UdpOptions) (int, int, bool) {
	var destination, source *core.PortRange
	if options != nil {
		destination, source = options.DestinationPortRange, options.SourcePortRange
	}
	if udp != nil {
		destination, source = udp.DestinationPortRange, udp.SourcePortRange
	}
	if source != nil {
		return 0, 0, false
	}
	if destination == nil || destination.Min == nil || destination.Max == nil {
		return 0, 0, true
	}
	return *destination.Min, *destination.Max, true
}

// normalize maps an OCI rule onto Rule. Features the reconciler does not
// model (source port ranges, ICMP type filters) set unsupported so the rule
// never matches a desired rule.
func normalize(rule core.SecurityRule) Rule {
	normalized := Rule{Direction: string(rule.Direction), Protocol: deref(rule.Protocol), Description: deref(rule.Description),
		Stateless: rule.IsStateless != nil && *rule.IsStateless}
	if rule.Direction == core.SecurityRuleDirectionIngress {
		normalized.Peer, normalized.PeerType = deref(rule.Source), string(rule.SourceType)
	} else {
		normalized.Peer, normalized.PeerType = deref(rule.Destination), string(rule.DestinationType)
	}
	if normalized.PeerType == PeerCIDR {
		normalized.PeerType = ""
	}
	low, high, ok := PortRange(rule.TcpOptions, rule.UdpOptions)
	normalized.PortMin, normalized.PortMax = low, high
	if !ok || rule.IcmpOptions != nil {
		normalized.unsupported = true
	}
	return normalized
}

func (a sdkAPI) ListRules(ctx context.Context, id string) ([]ObservedRule, error) {
	var rules []ObservedRule
	var page *string
	for range maxPages {
		response, err := a.network.ListNetworkSecurityGroupSecurityRules(ociclient.RequestContext(ctx), core.ListNetworkSecurityGroupSecurityRulesRequest{
			NetworkSecurityGroupId: new(id), Page: page})
		if err != nil {
			return nil, fmt.Errorf("list OCI NSG rules: %w", err)
		}
		for _, rule := range response.Items {
			rules = append(rules, ObservedRule{ID: deref(rule.Id), Rule: normalize(rule)})
		}
		if response.OpcNextPage == nil || *response.OpcNextPage == "" {
			return rules, nil
		}
		page = response.OpcNextPage
	}
	return nil, errors.New("OCI NSG rule list exceeds its page bound")
}

func addDetails(rule Rule) core.AddSecurityRuleDetails {
	details := core.AddSecurityRuleDetails{Direction: core.AddSecurityRuleDetailsDirectionEnum(rule.Direction),
		Protocol: new(rule.Protocol), IsStateless: new(rule.Stateless)}
	if rule.Description != "" {
		details.Description = new(rule.Description)
	}
	if rule.Direction == DirectionIngress {
		details.Source, details.SourceType = new(rule.Peer), core.AddSecurityRuleDetailsSourceTypeEnum(rule.peerType())
	} else {
		details.Destination, details.DestinationType = new(rule.Peer), core.AddSecurityRuleDetailsDestinationTypeEnum(rule.peerType())
	}
	details.TcpOptions, details.UdpOptions = PortOptions(rule)
	return details
}

// PortOptions returns the TCP or UDP destination-port options of rule, or
// nil options when the rule has no port range.
func PortOptions(rule Rule) (*core.TcpOptions, *core.UdpOptions) {
	if rule.PortMin == 0 {
		return nil, nil
	}
	ports := &core.PortRange{Min: new(rule.PortMin), Max: new(rule.PortMax)}
	switch rule.Protocol {
	case ProtocolTCP:
		return &core.TcpOptions{DestinationPortRange: ports}, nil
	case ProtocolUDP:
		return nil, &core.UdpOptions{DestinationPortRange: ports}
	}
	return nil, nil
}

func (a sdkAPI) AddRules(ctx context.Context, id string, rules []Rule) error {
	details := make([]core.AddSecurityRuleDetails, 0, len(rules))
	for _, rule := range rules {
		details = append(details, addDetails(rule))
	}
	_, err := a.network.AddNetworkSecurityGroupSecurityRules(ociclient.RequestContext(ctx), core.AddNetworkSecurityGroupSecurityRulesRequest{
		NetworkSecurityGroupId:                      new(id),
		AddNetworkSecurityGroupSecurityRulesDetails: core.AddNetworkSecurityGroupSecurityRulesDetails{SecurityRules: details}})
	if err != nil {
		return fmt.Errorf("add OCI NSG rules: %w", err)
	}
	return nil
}

func (a sdkAPI) RemoveRules(ctx context.Context, id string, ruleIDs []string) error {
	_, err := a.network.RemoveNetworkSecurityGroupSecurityRules(ociclient.RequestContext(ctx), core.RemoveNetworkSecurityGroupSecurityRulesRequest{
		NetworkSecurityGroupId:                         new(id),
		RemoveNetworkSecurityGroupSecurityRulesDetails: core.RemoveNetworkSecurityGroupSecurityRulesDetails{SecurityRuleIds: ruleIDs}})
	if err != nil {
		return fmt.Errorf("remove OCI NSG rules: %w", err)
	}
	return nil
}

func (a sdkAPI) UpdateTags(ctx context.Context, id, etag string, tags ociresource.Tags) error {
	request := core.UpdateNetworkSecurityGroupRequest{NetworkSecurityGroupId: new(id),
		UpdateNetworkSecurityGroupDetails: core.UpdateNetworkSecurityGroupDetails{
			FreeformTags: maps.Clone(tags.Freeform), DefinedTags: tags.Defined}}
	if etag != "" {
		request.IfMatch = new(etag)
	}
	if _, err := a.network.UpdateNetworkSecurityGroup(ociclient.RequestContext(ctx), request); err != nil {
		return fmt.Errorf("update OCI NSG tags: %w", err)
	}
	return nil
}
